//==============================================================================
bool TfContact::TestZ1Y2OutRandge()
{
    #ifdef SOFT_SIMULTE
        return false;
    #else
        int Pos1=MOT[MTestZ1].Gali_ReadPos();
        int Pos2=MOT[MTestZ1].Gali_ReadEncoderPos();
        Pos1-=Pos2;
        if(Pos1<0)
            Pos1=0-Pos1;

        if(Pos1>10)                                                             //Steven 20100728 :縮小範圍
            return true;
        Pos1=MOT[MTestY2].Gali_ReadPos();
        Pos2=MOT[MTestY2].Gali_ReadEncoderPos();
        Pos1-=Pos2;
        if(Pos1<0)
            Pos1=0-Pos1;

        if(Pos1>10)                                                             //Steven 20100728 :縮小範圍
            return true;
        return false;
    #endif
}
//==============================================================================
void TfContact::TestZ1Y2SetPos()
{
    int Pos2=ChangeToFloatNonPcnt((double)(MOT[MTestZ1].Gali_ReadEncoderPos()), (double)(MOT[MTestZ1].Motor->GearRatio));                                       //Steven 20100728 : 要加上齒輪比
    int Pos4=ChangeToFloatNonPcnt((double)(MOT[MTestY2].Gali_ReadEncoderPos()), (double)(MOT[MTestY2].Motor->GearRatio));                                       //Steven 20100728 : 要加上齒輪比
    char str[256];
    sprintf(str, "DP,%d,,%d", 0-Pos2, 0-Pos4);
    MOT[MTestY1].Gali_Command(str, __FUNC__);
}
//==============================================================================
bool TfContact::TestZ2Y1OutRandge()
{
    #ifdef SOFT_SIMULTE
        return false;
    #else
        int Pos1=MOT[MTestZ2].Gali_ReadPos();
        int Pos2=MOT[MTestZ2].Gali_ReadEncoderPos();
        Pos1-=Pos2;
        if(Pos1<0)
            Pos1=0-Pos1;

        if(Pos1>10)                                                             //Steven 20100728 :縮小範圍
            return true;

        Pos1=MOT[MTestY1].Gali_ReadPos();
        Pos2=MOT[MTestY1].Gali_ReadEncoderPos();
        Pos1-=Pos2;
        if(Pos1<0)
            Pos1=0-Pos1;

        if(Pos1>10)                                                             //Steven 20100728 :縮小範圍
            return true;
        return false;
    #endif
}
//==============================================================================
void TfContact::TestZ2Y1SetPos()
{
    int Pos1=ChangeToFloatNonPcnt((double)(MOT[MTestY1].Gali_ReadEncoderPos()), (double)(MOT[MTestY1].Motor->GearRatio));                                       //Steven 20100728 : 要加上齒輪比
    int Pos3=ChangeToFloatNonPcnt((double)(MOT[MTestZ2].Gali_ReadEncoderPos()), (double)(MOT[MTestZ2].Motor->GearRatio));                                       //Steven 20100728 : 要加上齒輪比
    char str[256];
    sprintf(str, "DP%d,,%d", Pos1, 0-Pos3);
    MOT[MTestY1].Gali_Command(str, __FUNC__);
}
