//---------------------------------------------------------------------------
void __fastcall TfContact::FormClose(TObject *Sender, TCloseAction &Action)
{
    OTDTimer->Enabled=false;                                                    //Steven 20140404 : Fixed OTD
    TimerEP->Enabled=false;
    timerContact->Enabled=false;                                                //JerryYang 20251118 : 機台有IC不能切換模式
    fShow=false;
    ReadFile();
    DoIniDataToForm();                                                          //JerryYang 20250411 : 離開頁面要刷新一次, 避免誤存檔
    SystemStart=false;                                                          //Steven 20091002 : Form Close時,機台要停住!!
    iGPIBIndexStatus=Z1_Z2_Normal;

    palSFCInformation->Visible=false;
    bLampManualSetp=false;                                                      //Steven 20100223 : 離開後燈要滅掉
    bLampManualStart=false;                                                     //Steven 20100223 : 離開後燈要滅掉
    bDoRTCLearning=false;                                                       //Ifor 20260226 add: Contact Mode 執行RTC Learn 不開啟Hot Air

    if(CarlibrationTask!=1)
    {
        fAllMotorHome=false;
    }
    edPinCount->Enabled=true;
    edForcePerPinN->Enabled=true;
    edForcePerPinG->Enabled=true;

    if(iContactMode!=CONTACT_NORMAL)                                            //JerryYang 20181212 (Steven) : fix all site drop error
    {
        fLtcSensor->GetLtcSensor(1);                                            //Steven 20230118 : 將Latch清空，確保沒有問題
        fLtcSensor->GetLtcSensor(0);

        for(int i=0; i<FTestSuck.iShtRow; i++)                                  //jou 2011-07-01 start : 解決未完成auto high中途退出會一直出現need one cycle error
        {
            for(int j=0; j<FTestSuck.iShtCol; j++)
            {
                FTestSuck.SetItemData(i, j, iFTestBackItem[i][j]);
                BTestSuck.SetItemData(i, j, iBTestBackItem[i][j]);
            }
        }
    }

    if(iContactMode==STEP_CONTACT_TEST ||                                       //Steven 20150811 : Step by Step Contact Test
       iContactMode==CONTACT_DEVICE_MAP_CHECK)                                  //Steven 20191009 : Device Map for Qualcomm
    {
        if(MOT[MMTrayY].HasIC())
        {
            MOT[MMTrayY].ClearTray(__FUNC__);
        }
    }

    if(bNeedWaitContactTestAutoVerify)                                          //JerryYang 20220215 : RTC Auto Verify half view check
    {
        ShowMyMessage("RTC Autoverify NG");
    }

    NewRecordProcess("MES2170", "Exit Contact");

    iContactMode=CONTACT_NORMAL;                                                //kevin 20130625
    rbModeNormal->Checked=true;                                                 //Steven 20170605 : 修改顯示
    SetContactMode();                                                           //Steven 20170605 : 修改顯示
    cbOneTouchAutoContactHight->Checked=false;                                  //Ifor 20220803 add 一鍵完成Auto Contact Hight

    if(bSetHasIC)                                                               //Steven 20190626 : Fixed 2DID error in contact test
    {
        FLCarryKit.SetAll(NULL_IC);
        BLCarryKit.SetAll(NULL_IC);
        bSetHasIC=false;
    }

    if((SHUTTLE_SENSOR_TYPE==eSensorEtherCAT   ||
        SHUTTLE_SENSOR_TYPE==eSensorEtherCAT3) &&
        In_Shuttle_Auto_Latch==eInSHAutoLtc    &&
        fCCLink->bShow==false)                                                  //KenHsieh 20251121 : 修正使用EtherCAT 無法讀取shuttle sensor 之問題
        MyEtherCAT->Pause();

    bIndexCheckVacum=false;                                                     //kevin 20200716 add ASE_KH 卡輸入
    if(REAL_TIME_CCD)                                                           //Sam 20240711 : RTC Auto Tuning
    {
        cbRTCAutoTuning->Checked=false;
        bOldRTCAutoTuning=false;
    }
    //這一行請保持在最下面!!-----------------
//    myLog.Do_Log(Sender, asUser, asLogPath);    //Steven 20100629
}
//---------------------------------------------------------------------------
void __fastcall TfContact::ShowArmAndDeviceForce()
{
    edForcePerDeviceKG->Color=clWhite;
    edForcePerDeviceN->Color=clWhite;
    edAirForce->Color=clWhite;

    double dBallCount=atof(edPinCount->Text.c_str());                           //腳數
    double dSingleN=atof(edForcePerPinN->Text.c_str());                         //牛頓
    double dSingleGf=atof(edForcePerPinG->Text.c_str());                        //gf

    iTotalGf=CalculateTotalAirForce(dBallCount, dSingleGf);                     //JimmyChiu 20220119 獨立計算空氣壓力
    DeviceForm.dPress=iTotalGf;

//    double dDeviceN=dBallCount*dSingleN;                                        // device要壓的牛頓
//    double dDeviceGf=dBallCount*dSingleGf*0.001;                                // device要壓的公斤     //JimmyChiu 20220119 /1000=>*0.001
    double dDeviceN  = CalcDeviceForce(dBallCount, dSingleN, dSingleGf, false); //AI(ht9045-contact-force) 20260624 (RogerYang) : 統一公式(N)
    double dDeviceGf = CalcDeviceForce(dBallCount, dSingleN, dSingleGf, true);  //AI(ht9045-contact-force) 20260624 (RogerYang) : 統一公式(Kgf)
    edForcePerDeviceKG->Text=FormatFloat("0.0000", dDeviceGf);                  //秀出一個ic要壓的公斤
    edForcePerDeviceN->Text =FormatFloat("0.0000", dDeviceN);                   //秀出一個ic要壓的牛頓

    edAirForce->Text =FormatFloat("0.0000", iTotalGf);
    edAirForceN->Text=FormatFloat("0.0000", iTotalGf*9.8);                      //JerryYang (Steven) 20161215 改由KG換算成牛頓,避免在下限時顯示的kgf跟N力量不同
}
//-----------------------------------------------------------------------------
void __fastcall TfContact::edPinCountChange(TObject *Sender)
{
    if(fShow==false)                                                            //JimmyChiu 20220121 add
        return;
    ShowArmAndDeviceForce();
}
//---------------------------------------------------------------------------
void __fastcall TfContact::edForcePerPinNChange(TObject *Sender)
{
    if(fShow==false)                                                            //JimmyChiu 20220121 add
        return;
    double f;
    if(CosFunction.bForecePerPinKGf==false)                                     //JerryYang 20180515 : 輸入每個pin的力量,單位以kgf為主,避免轉換成牛頓又換回KGf會有小數點兩位的差異
    {
        f=atof(edForcePerPinN->Text.c_str());
        f=f*1000.0/9.8;
        edForcePerPinG->Text=FormatFloat("0.0000", f);
        ShowArmAndDeviceForce();
    }
}
//---------------------------------------------------------------------------
void __fastcall TfContact::edDieForcePerPinGChange(TObject *Sender)
{
    if(fShow==false)                                                            //JimmyChiu 20220121 add
        return;
    double f;
    f=atof(edDieForcePerPinG->Text.c_str());
    f=f*9.8/1000.0;
    edDieForcePerPinN->Text=FormatFloat("0.0000", f);

    f=atof(edForcePerPinG->Text.c_str());
    f=f*9.8/1000.0;
    edForcePerPinN->Text=FormatFloat("0.0000", f);

    ShowArmAndDeviceForce();
    if(INSTALL_DOUBLE_EP!=0)
        CountDieForceKg(true);                                                  //Steven 20210202 : Pin force被改變時, due force需要連動變更
}
//---------------------------------------------------------------------------
void __fastcall TfContact::DutCount()
{
    AnsiString asStr;
    switch(TestIF_File.iTestMode)                                               //jou 2014-09-06 修正開啟程式的時候EP異常
    {
        case SingleSite:
            dDutCount=1;
            break;
        case DualSite:                                                          //1x2
        case QualSite2X2N:                                                                                              //Frank 20200520 2X2NN Mode
//        case DualSiteBS: //1x1 busyshuttle
            if(IniConfig.bD27UseSingleSite85kg==true)
            {
                if((LastSet.bUseTestSocket[0][0][1]==false && LastSet.bUseTestSocket[1][0][1]==false)  ||               //ChungHung 20130910 alter for SCK can close site by Index
                   (LastSet.bUseTestSocket[0][0][0]==false && LastSet.bUseTestSocket[1][0][0]==false))                  //Steven 20110915 : 1x2關Site,單Dut要可以壓到85KG
                    dDutCount=1;
                else
                    dDutCount=2;
            }
            else
            {
                dDutCount=2;
            }
            break;
        case DualSite2x1:
            if(IniConfig.bD27UseSingleSite85kg==true)
            {
                if((LastSet.bUseTestSocket[0][1][0]==false && LastSet.bUseTestSocket[1][1][0]==false) ||                //ChungHung 20130910 alter for SCK can close site by Index
                   (LastSet.bUseTestSocket[0][0][0]==false && LastSet.bUseTestSocket[1][0][0]==false))                  //Steven 20110915 : 1x2關Site,單Dut要可以壓到85KG
                    dDutCount=1;
                else
                    dDutCount=2;
            }
            else
            {
                dDutCount=2;
            }
            break;
        case _6Site2X3N:                                                        //Steven 20220425 : 2X3NN Mode
        case TriSite1X3:
            dDutCount=3;
            break;
        case QualSite1X4:                                                       //1x4
        case QualSite2X2:                                                       //2x2
        case _8Site1X4:                                                         //ChungHung 20150528 add for 海思 _8Site1x4
        case _8Site2X4N:                                                        //Wei 20231211 : 2X4NN Mode
//        case QualSite2X2BS: //2x2 busyshuttle
            dDutCount=4;
            break;
        case _6Site2X3:                                                         //ChungHung 20140115 add for 2x3_6
            dDutCount=6;
            break;
        case _8Site2X4:                                                         //2x4
            if(TestIF_File.bOctal_12Kit)                                        //ChungHung 20140508 add for SCK
                dDutCount=12;
            else
                dDutCount=8;
            break;
        case _10Site2X5:                                                        //wei 20190614 10 site
            dDutCount=10;
            break;
        case _12Site2X6:
            dDutCount=12;
            break;
        case _16Site2X8:                                                                                                                                        //2x8
            if(TestIF_File.iSiteMap[0][0]<=0 && TestIF_File.iSiteMap[0][2]<=0 && TestIF_File.iSiteMap[0][4]<=0 && TestIF_File.iSiteMap[0][6]<=0 &&
               TestIF_File.iSiteMap[1][0]<=0 && TestIF_File.iSiteMap[1][2]<=0 && TestIF_File.iSiteMap[1][4]<=0 && TestIF_File.iSiteMap[1][6]<=0)                //Steven 20221122 : 16 site關site壓力顯示修正
            {
                dDutCount=8;
            }
            else if(TestIF_File.iSiteMap[0][1]<=0 && TestIF_File.iSiteMap[0][3]<=0 && TestIF_File.iSiteMap[0][5]<=0 && TestIF_File.iSiteMap[0][7]<=0 &&
                    TestIF_File.iSiteMap[1][1]<=0 && TestIF_File.iSiteMap[1][3]<=0 && TestIF_File.iSiteMap[1][5]<=0 && TestIF_File.iSiteMap[1][7]<=0)           //Steven 20221122 : 16 site關site壓力顯示修正
            {
                dDutCount=8;
            }
            else if(TestIF_File.iSiteMap[0][0]<=0 && TestIF_File.iSiteMap[0][2]<=0 && TestIF_File.iSiteMap[0][4]<=0 && TestIF_File.iSiteMap[0][6]<=0 &&
                    TestIF_File.iSiteMap[1][1]<=0 && TestIF_File.iSiteMap[1][3]<=0 && TestIF_File.iSiteMap[1][5]<=0 && TestIF_File.iSiteMap[1][7]<=0)
            {
                dDutCount=8;
            }
            else if(TestIF_File.iSiteMap[0][1]<=0 && TestIF_File.iSiteMap[0][3]<=0 && TestIF_File.iSiteMap[0][5]<=0 && TestIF_File.iSiteMap[0][7]<=0 &&
                    TestIF_File.iSiteMap[1][0]<=0 && TestIF_File.iSiteMap[1][2]<=0 && TestIF_File.iSiteMap[1][4]<=0 && TestIF_File.iSiteMap[1][6]<=0)
            {
                dDutCount=8;
            }
            else if(iCloseSiteModeFor2x8>e2x8Standard)                          //Steven 20260420 : != --> >
            {
                dDutCount=8;
            }
            else
            {
                dDutCount=16;
            }
            break;
        case _16Site4X4:                                                        //Sam 20190226 : 16Site4X4
            dDutCount=8;                                                        //KenHsieh 20230313 : NN Mode Dutcount新增
            break;
        case _32Site4X8N:
            dDutCount=16;                                                       //KenHsieh 20230313 : NN Mode Dutcount 32 -> 16
            break;
    }

    if(TestIF_File.iTestMode==SingleSite)                                       //JerryYang 20171215 (Steven) Single site只支援浮動頭1對1或是2對1
    {
        if(scrbSLK->Position==3 || scrbSLK->Position==6)
            scrbSLK->Position=5;
        else if(scrbSLK->Position==4)
            scrbSLK->Position=2;
    }
    DeviceForm_File.iHeadDeviceCT=scrbSLK->Position;                            //jou 2014-04-24 修正選擇head數時,force值不會馬上改變
    asStr.sprintf("%sContact%d.bmp", BmpPath, scrbSLK->Position);
    imgSLK->Picture->LoadFromFile(asStr);                                       //JimmyChiu 20220121 str[64]=>AnsiString asStr
    //ShowArmAndDeviceForce();                                                  //JimmyChiu 20220121 mark 改變階層
}
