//---------------------------------------------------------------------------
void __fastcall TfContact::edDropWaitTimeMouseDown(TObject *Sender,
      TMouseButton Button, TShiftState Shift, int X, int Y)
{
    TEdit *Buffer;
    Buffer=(TEdit *)Sender;
    if(Buffer->Tag==1)
    {
        if(Barcode_Reader(bcContact)==0)                                        // 20140103 wei KYEC Barcode Reader
        {
            return;
        }
    }
    fQwertyKey->ShowQwertyKey((TEdit *)Sender, N_DOUBLE, 3, false);

    if(CUSTOMER_CODE==CC_HANA_MICRON)                                           //Steven 20191219 : Hana micron說丟料跟吸料高度要可以一樣高
    {
        if(atof(edReleaseHeight1->Text.c_str())<atof(edPickUp1->Text.c_str()))
            edReleaseHeight1->Text=atof(edPickUp1->Text.c_str());
        if(atof(edReleaseHeight2->Text.c_str())<atof(edPickUp2->Text.c_str()))
            edReleaseHeight2->Text=atof(edPickUp2->Text.c_str());
    }
    else                                                                        //jou 2012-12-04 增加保護,Release Height 一定要比 Pick Height 高 1mm 。
    {
        if(atof(edReleaseHeight1->Text.c_str())<(atof(edPickUp1->Text.c_str())+1.00))
            edReleaseHeight1->Text=atof(edPickUp1->Text.c_str())+1.00;
        if(atof(edReleaseHeight2->Text.c_str())<(atof(edPickUp2->Text.c_str())+1.00))
            edReleaseHeight2->Text=atof(edPickUp2->Text.c_str())+1.00;
    }

    if(atof(edContactHeight1->Text.c_str())>=0.0)
        edContactHeight1->Text="1";                                             //kevin 20180222 0-> 1
    if(atof(edContactHeight2->Text.c_str())>=0.0)
        edContactHeight2->Text="1";                                             //kevin 20180222 0-> 1
    if(atof(edContactHeight1->Text.c_str())<=fIndexDownPos)
        edContactHeight1->Text=AnsiString(fIndexDownPos);
    if(atof(edContactHeight2->Text.c_str())<=fIndexDownPos)
        edContactHeight2->Text=AnsiString(fIndexDownPos);

    if(cbContactMode->ItemIndex==DirectContactModeDiffentSpeed ||
       DeviceForm.ContactMode==TMoveSlowContact)                                //Steven 20160130 : TMove Soft contact
    {
       if(atof(edDropOffset1->Text.c_str())<2.0)
            edDropOffset1->Text="2";
    }
    else
    {
        if(atof(edDropOffset1->Text.c_str())<=0.0)
            edDropOffset1->Text="0";
    }

    if(atof(edDropOffset1->Text.c_str())>=10.0)
        edDropOffset1->Text="10";

    if(cbContactMode->ItemIndex==DirectContactModeDiffentSpeed ||
       DeviceForm.ContactMode==TMoveSlowContact)                                //Steven 20160130 : TMove Soft contact
    {
        if(atof(edDropOffset2->Text.c_str())<2.0)
            edDropOffset2->Text="2";
    }
    else
    {
        if(atof(edDropOffset2->Text.c_str())<=0.0)
            edDropOffset2->Text="0";
    }

    if(atof(edDropOffset2->Text.c_str())>=10.0)
        edDropOffset2->Text="10";

    if(atof(edYDimension->Text.c_str())<=2.0)                                   //jou 20180301 (Steven) : 修正IC size無法修改浮點數
        edYDimension->Text="2.0";
    else if(atof(edYDimension->Text.c_str())>=UserDefForm_File[TrayForm.Loader.iTrayType].YPitch)                       //wei 20150325  ic大小最大限制在Tray的Y pitch
        edYDimension->Text=UserDefForm_File[TrayForm.Loader.iTrayType].YPitch;  //jou 20171024 (wei) : 修正contect form ic size範圍錯誤

    edYDimension->Text=FormatFloat("0.00", edYDimension->Text.ToDouble());

    if(atof(edXDimension->Text.c_str())<=2.0)                                   //jou 20180301 (Steven) : 修正IC size無法修改浮點數
    {
        edXDimension->Text="2.0";
    }
    else if(LoadForm->XDivision==1 ||                                           //jou 20171019 (wei) : LoadForm->XPitch -> UserDefForm_File[TrayForm.Loader.iTrayType].XDivision
            UserDefForm_File[TrayForm.Loader.iTrayType].XPitch<=0)              //Steven 20220610 : 針對Tray只有一排的做保護
    {
        if(atof(edXDimension->Text.c_str())>=130.0)
            edXDimension->Text="130.0";
    }
    else if(atof(edXDimension->Text.c_str())>=UserDefForm_File[TrayForm.Loader.iTrayType].XPitch)                       //wei 20150325  ic大小最大限制在Tray的X pitch
    {
        edXDimension->Text=UserDefForm_File[TrayForm.Loader.iTrayType].XPitch;  //jou 20171024 (wei) : 修正contect form ic size範圍錯誤
    }

    edXDimension->Text=FormatFloat("0.00", edXDimension->Text.ToDouble());

    if(atoi(edDropSpeed->Text.c_str())>100)
        edDropSpeed->Text="100";
    if(atoi(edDropSpeed->Text.c_str())<1)
        edDropSpeed->Text="1";

    if(CosFunction.bFixedDropSpeed)                                             //Steven 20131101 : 使用固定的Drop速度
    {
        if(atof(edDropSpeed->Text.c_str())>CosFunction.iFixedDropSpeed)
        {
            edDropSpeed->Text=AnsiString(CosFunction.iFixedDropSpeed);
        }
    }

    if(atof(edDropWaitTime->Text.c_str())>10)
        edDropWaitTime->Text="10.0";
    if(atof(edDropWaitTime->Text.c_str())<0.01)                                 //Steven 20210723 : edDropWaitTime 0.1 --> 0.01
        edDropWaitTime->Text="0.01";

    if(atof(edUpWaitTime->Text.c_str())>10)                                     //Ifor 20210111 add:
        edUpWaitTime->Text="10.0";
    if(atof(edUpWaitTime->Text.c_str())<0.1)
        edUpWaitTime->Text="0.1";

    if(atoi(edUpSpeed->Text.c_str())>100)
        edUpSpeed->Text="100";
    if(atoi(edUpSpeed->Text.c_str())<1)
        edUpSpeed->Text="1";

    if(atoi(edtTorqueMax->Text.c_str())>150)
        edtTorqueMax->Text="150.0";
    if(atoi(edtTorqueMax->Text.c_str())<1)
        edtTorqueMax->Text="1.0";

    if(atoi(edtTorqueCmp->Text.c_str())>30)
        edtTorqueCmp->Text="30.0";
    if(atoi(edtTorqueCmp->Text.c_str())<10)
        edtTorqueCmp->Text="10.0";

    if(IniConfig.bKoreaFunction)                                                //ChungHung 20150517 add for ATK Try to Fix TSMC Device Die Crack Issue start
    {
        edtPurgeBeforePickShuttleTime->Text = atoi(edtPurgeBeforePickShuttleTime->Text.c_str());
        if(atoi(edtPurgeBeforePickShuttleTime->Text.c_str())>10)
            edtPurgeBeforePickShuttleTime->Text="10";
        if(atoi(edtPurgeBeforePickShuttleTime->Text.c_str())<1)
            edtPurgeBeforePickShuttleTime->Text="1";

        edtPurgeBeforePickShuttleInterval->Text = atoi(edtPurgeBeforePickShuttleInterval->Text.c_str());
        if(atoi(edtPurgeBeforePickShuttleInterval->Text.c_str())>10)
            edtPurgeBeforePickShuttleInterval->Text="10";
        if(atoi(edtPurgeBeforePickShuttleInterval->Text.c_str())<1)
            edtPurgeBeforePickShuttleInterval->Text="1";

        edtPurgeBdforePickShuttleOffSet->Text = atoi(edtPurgeBdforePickShuttleOffSet->Text.c_str());
        if(atoi(edtPurgeBdforePickShuttleOffSet->Text.c_str())>10)
            edtPurgeBdforePickShuttleOffSet->Text="10";
        if(atoi(edtPurgeBdforePickShuttleOffSet->Text.c_str())<1)
            edtPurgeBdforePickShuttleOffSet->Text="1";
    }
}
