//---------------------------------------------------------------------------
void __fastcall TfContact::cbContactModeChange(TObject *Sender)
{
    AnsiString szDir="";

    if(CosFunction.bFixedDropSpeed)                                             //Steven 20131101 : 使用固定的Drop速度
    {
        edDropOffset1->Enabled=false;
        edDropOffset2->Enabled=false;
    }
    else
    {
        edDropOffset1->Enabled=true;                                            //2012-01-03    Dell
        edDropOffset2->Enabled=true;                                            //2012-01-03    Dell
    }

    if(cbContactMode->ItemIndex==DropPlaceShiftContact)                         //Steven 20220607 : DropPlaceShiftContact模式已不使用, 自動跳下一個
    {
        cbContactMode->ItemIndex=DropContactModeDiffentSpeed;
    }

    if(cbContactMode->ItemIndex==DirectContactMode ||                           //Steven 20100406 丟測模式會自動把Offset改成2mm
       cbContactMode->ItemIndex==TMove)
    {
        edDropOffset1->Text=0;
        edDropOffset2->Text=0;
        edDropOffset1->Enabled=false;                                           //2012-01-03    Dell
        edDropOffset2->Enabled=false;                                           //2012-01-03    Dell
    }
    else if(cbContactMode->ItemIndex==DropContact ||
            cbContactMode->ItemIndex==DropContactModeDiffentSpeed ||
            cbContactMode->ItemIndex==TMoveDrop ||
            cbContactMode->ItemIndex==TMoveDropSlowContact ||
            cbContactMode->ItemIndex==DropPlaceShiftContact)                    //ChungHung 20150528 add for 海思 _8Site1x4
    {
        if(CUSTOMER_CODE==CC_KYEC_CHEN && IniConfig.bA16ContactTestDropContact)                                         //wei 20150831
        {
            edDropOffset1->Text=0;
            edDropOffset2->Text=0;
        }
        else
        {
            if(cbContactMode->ItemIndex==DropContact &&
               CUSTOMER_CODE==CC_PTI)                                           //Sam 20190225 : 力成 DirectContact & DropContact 切換後，DropContact 的 Drop 不要變成預設值
            {
                szDir=GetRecipeFileName("Contact.Data");
                edDropOffset1->Text=FormatFloat("0.00", ReadIniData(szDir, "Test Arm1", "Drop_DropContactMode",    2.0));
                edDropOffset2->Text=FormatFloat("0.00", ReadIniData(szDir, "Test Arm2", "Drop_DropContactMode",    2.0));
            }
            else
            {
                edDropOffset1->Text=2;
                edDropOffset2->Text=2;
            }
        }
    }
    else if(cbContactMode->ItemIndex==DirectContactModeDiffentSpeed ||
            cbContactMode->ItemIndex==TMoveSlowContact ||                       //Steven 20160130 : TMove Soft contact
            cbContactMode->ItemIndex==DropContactSoftEP)                        //kevin 20220621 add drop soft mode
    {
        if(atoi(edDropOffset1->Text.c_str())<2)
        {
            edDropOffset1->Text="2";
        }

        if(atoi(edDropOffset2->Text.c_str())<2)
        {
            edDropOffset2->Text="2";
        }
    }
    else                                                                        //kevin 20220621 add other mode 清為 0
    {
        edDropOffset1->Text=0;
        edDropOffset2->Text=0;
    }

    if((cbContactMode->ItemIndex==DropContact ||
        cbContactMode->ItemIndex==TMoveDrop) &&                                 //JerryYang 20240111 : add
        CosFunction.bTesterSidePushFunction==true)                              //Richard 20220321 : 渠梁Side Push
    {
        pnlSidePush->Visible=true;
    }
    else
    {
        pnlSidePush->Visible=false;
    }
}
//---------------------------------------------------------------------------
void __fastcall TfContact::pnlSensorAdjClick(TObject *Sender)
{
    if(fSecurity->Insufficient(109)==false)                                     //Ifor 20151103 : 新增Contact 畫面中Sensor Adjustment權限    //JerryYang 20160819 修正Contact存檔誤卡sensor adjust權限問題
        return;
    fCCLink->ShowUseSensor(TestIF.iTestMode, TestIF.dSiteXPitch);
    fCCLink->Show();
}
//---------------------------------------------------------------------------
void __fastcall TfContact::spbSaveClick(TObject *Sender)
{
    if(IniConfig.bA02DisableSaveParsWhenSwitchToOp==true &&                     //RogerYang 20260305 張寧說時間到都要登出，且不可被更改任何設定(A01_2)
        AccessLevel==0)
    {
        ShowMyMessage("[A01_2]目前已切換到Operator權限，\r\n請重新登入再做設定!");
        if(CarlibrationTask!=1)
        {
            ShowMyMessage("""Auto Height""/""Contect Test"" Mode need Finish !!", "需要完成""Auto Height""/""Contect Test""!!");
            return;
        }
        Close();
    }

    int ret=0;
    AnsiString str1="";
    double position1=0.0, position2=0.0, position3=0.0;
    if(chk_K_Temperature->Checked==true)                                        //Ztex 2024.03.26 Add Contact Mode K Temperature
        return;

    if(INSTALL_DOUBLE_EP!=0)
    {
        if(dOldDieForceKitDiameter!=DeviceForm_File.dDieForceKitDiameter)
        {
            ShowMyMessage("The Diameter bore has changed.Please confirm the KG setting value again.!","直徑有變動，請重新確認KG設定值。!");
            dOldDieForceKitDiameter=DeviceForm_File.dDieForceKitDiameter;
        }
    }

    if(IniConfig.bEnable_SECS_GEM==true)                                        //JerryYang 20170213 (Steven) 矽品騰清要求修改Run check觸發條件,此段要放在SaveSetupFile之前
    {
        if(CheckContactSettingChange()==true)
        {
            bHasSaveSet=true;
        }
        EventReport(SECS_EVENT.SaveRecipe);
    }

    if(CUSTOMER_CODE==CC_KYEC_LEE)
    {
        str1="";
        position1=atof(ConvertTouMType(Get0_01MMType(edContactHeight1->Text.c_str())));
        position2=atof(ConvertTouMType(Get0_01MMType(asContactHeight[0].c_str())));
        position3=position1-position2;
        if(position3<0)
        {
            position3*=-1;
        }

        if(position3>IniConfig.dD68DistanceRange)
        {
            str1.sprintf("Arm1 Before Auto Height Pos =%smm,After Auto Height Pos=%s", asContactHeight[0].c_str(), edContactHeight1->Text.c_str());
            ret=ShowMyMessageBox_YES_NO(str1, "Do you want to change?");
            if(ret!=1)
            {
                edContactHeight1->Text=asContactHeight[0];
            }
        }

        str1="";
        position1=atof(ConvertTouMType(Get0_01MMType(edContactHeight2->Text.c_str())));
        position2=atof(ConvertTouMType(Get0_01MMType(asContactHeight[1].c_str())));
        position3=position1-position2;
        if(position3<0)
        {
            position3*=-1;
        }

        if(position3>IniConfig.dD68DistanceRange)
        {
            str1.sprintf("Arm2 Before Auto Height Pos =%smm,After Auto Height Pos=%s", asContactHeight[1].c_str(), edContactHeight2->Text.c_str());
            ret=ShowMyMessageBox_YES_NO(str1, "Do you want to change?");
            if(ret!=1)
            {
                edContactHeight2->Text=asContactHeight[1];
            }
        }
    }
    SaveSetupFile(GetRecipePath(), GetLastOpenFN());                            //kevin 20150105
    #ifdef ASE_KaohSiung
        fBuilder->bSaveAsJobFile(GetLastOpenFN(), "JOBFILE");
    #endif
    ReadFile();
    DoIniDataToForm();                                                          //kevin 20180402 add refesh show data
    if(bAutoHighFinish==true)
    {
        fOffSet->ClearIndexOffset();
        bAutoHighFinish=false;
    }
    spbSave->Down=false;
    bHeightCalibrationFinish=true;                                              //JerryYang 20151103 做完Height Calibration
    if(CUSTOMER_CODE==CC_KYEC_LEE)                                              //Ifor 20181130 : add KYEC 要求顯示Contact高度
    {
        double position1,position2;
        position1=atof(ConvertTouMType(Get0_01MMType(edContactHeight1->Text.c_str())));
        position2=atof(ConvertTouMType(Get0_01MMType(edContactHeight2->Text.c_str())));
        fMain->LabZ1_Test->Caption=position1;
        fMain->LabZ2_Test->Caption=position2;
    }

    fMain->BackupSetupFile();                                                   //Ifor 20170620 (wei) add Auto BackUp Setup File & Last Data
    if(INSTALL_DOUBLE_EP==DOUBLE_EP_NORMAL || INSTALL_DOUBLE_EP==DOUBLE_EP_MULTI)   //AI(ht9045-v899) 20260430: extend DoubleForce write to Multi EP half.
    {
        int iInputValue=0;
        iInputValue=TransformFuntion(DeviceForm_File.DoubleForce, true);
        //AI(ht9045-v899) 20260526: Multi EP Die Force SAVE flushes the computed per-site iAPAXEPValue instead of one common direct value.
        if(INSTALL_DOUBLE_EP==DOUBLE_EP_MULTI && IsMultiEPPressureRouteActive()==true)
            APAX_WriteData(false, 0);
        else
            ADAM_DirectWriteData(iInputValue, 0, 0);
    }

    //AI(ht9045-v899) 20260526: TfContact SAVE must refresh independent/Multi EP site outputs after site trim changes.
    if(IsIndependentEPPressureRouteActive()==true)
        ADAM_WriteVoltage(DeviceForm.dPress);

    if(TestIF_File.bEnableReadAndCheckTorque)                                   //kevin 20211211 change
    {
        bResetArm1Value=true;
        bResetArm2Value=true;
        bResetRecordSetArm1Value=false;
        bResetRecordSetArm2Value=false;
        iReadTorqueError=0;
    }

    if(USE_VibrationCommunication)                                              //JerryYang 20230814 : add震動馬達通訊調速版本
    {
        dmTrayMotor->bNeedSetVibrateMotSpeed=true;
    }
}
