    WriteIniData(szDir, "Torque Control", "Double Force",                       edDoubleForce->Text);                   //Ifor 20190104 : Add Double EP Control
    WriteIniData(szDir, "Torque Control", "Pin of Die",                         edtPinOfDie->Text);                     //Steven 20191106: Pin of Die

    WriteIniData(szDir, "Height Calibration", "Auto Contact Test Count",        edAutoContactTest->Text);               //Steven 20150224 : Auto Contact Test   //Steven 20180619 (Jou)

    WriteIniData(szDir, "Torque Control", "Die Force Per Pin",                  edDieForcePerPinN->Text);
    WriteIniData(szDir, "Torque Control", "Die Force Per Pin Kg",               edDieForcePerPinG->Text);
    WriteIniData(szDir, "Height Calibration", "Test Contact Count",             edTestContactCount->Text);              //KevinCheng 20260115 : NV Contact Test
