//---------------------------------------------------------------------------
TQPF_Timer HFullViewCheckDelay;
void TfContact::InitDoFullViewCheck()                                           //ChungHung 20130122 add for SCK
{
    iDoFullViewCheck=1;
}
//---------------------------------------------------------------------------
bool TfContact::DoFullViewCheck()                                               //ChungHung 20130122 add for SCK
{
    bool flag;
    int &Task=iDoFullViewCheck;
    AnsiString ErrPart="";

    switch(Task)
    {
        case 1:
            COM2->bRealTimeCom_ReceiveOK[COM2->rtFullMOK]=false;
            COM2->bRealTimeCom_ReceiveOK[COM2->rtFullMNG]=false;
            COM2->SendCommToVision(COM2->rtFullMOK, false);
            HFullViewCheckDelay.SetSecAndOn(10);
            Task=100;
            break;
        case 100:
            if(COM2->bRealTimeCom_ReceiveOK[COM2->rtFullMOK]==true)
            {
                Task=200;
            }
            else if(COM2->bRealTimeCom_ReceiveOK[COM2->rtFullMNG]==true)
            {
                ShowMyMessage("RTC no Full View Modal Please Check RTC System", "RTC 沒Full View Modal 請確認RTC系統");
                Task=1;
            }
            else
            {
                if(HFullViewCheckDelay.Off())
                {
                    ShowMyMessage("RTC Check Full View Modal time out!!!", "確認Full View Modal逾時!!!");
                    Task=1;
                }
            }
            break;
        case 200:                                                               //jou 2012-03-29 RTC啟動時,自動將燈箱打開
            COM2->SendCommToVision(COM2->rtLightOn, true);
            HFullViewCheckDelay.SetSecAndOn(10);
            Task=300;
            break;
        case 300:                                                               //初始化,紀錄要跑的位置
            if(REAL_TIME_CCD==true && !COM2->bCCDDummyRum)
            {
                if(COM2->bRealTimeCom_ReceiveOK[COM2->rtLightOn]==false)        //jou 2012-03-29 RTC啟動時,自動將燈箱打開
                {
                    if(HFullViewCheckDelay.Off())
                    {
                        ShowMyMessage("RTC Light On Fail!!","RTC光源開啟失敗!!");
                        Task=200;
                        break;
                    }
                    break;
                }
            }
            Task=400;
            break;
        case 400:
            flag=MOT[MTestZ1].Gali_Two_ZAxis_Move(Prod.TestZ1_Safe, GotIndexZSpeed(iSpeedZ*1000), __FUNC__);

            if(flag)
                Task=500;
            break;
        case 500:
            if(MOT[MTestY1].GalilTwoY_Move(Prod.TestY1_Front, Prod.TestY2_Rear, GotIndexYSpeed(iSpeed*3000), __FUNC__))                                         //2008/10/20 lee    //JimmyChiu 20211028 : All speed can set by speed setting.
            {
                COM2->bRealTimeCom_ReceiveOK[COM2->rtFullTOK]=false;
                COM2->bRealTimeCom_ReceiveOK[COM2->rtFullTNG]=false;
                COM2->SendCommToVision(COM2->rtCHECKNULL, true);
                COM2->SendCommToVision(COM2->rtFullTOK,true);
                HFullViewCheckDelay.SetSecAndOn(10);
                Task=600;
            }
            break;
        case 600:
            if(COM2->bRealTimeCom_ReceiveOK[COM2->rtFullTOK]==true)
            {
                return true;
            }
            else if(COM2->bRealTimeCom_ReceiveOK[COM2->rtFullTNG]==true)
            {
                ShowMyMessage("RTC Full View Check Fail!!!", "RTC Full View 確認失敗");
                Task=1;
            }
            else
            {
                if(HFullViewCheckDelay.Off())
                {
                    ShowMyMessage("RTC Full View Time Out!!!", "RTC Full View 逾時");
                    Task=1;
                }
            }
            break;
    }
    return false;
}
