//---------------------------------------------------------------------------
void TfContact::SetContactMode()                                                //Steven 20150224 : Auto Contact Test
{
    if(rbModeNormal->Checked)
    {
        iContactMode=CONTACT_NORMAL;
        if(CUSTOMER_CODE==CC_KYEC_CHEN &&
           IniConfig.bA16ContactTestDropContact)                                //wei 20150831
        {
            ChangeContactMode(false);
        }
        Memo1->Lines->Add("CONTACT_NORMAL");
    }
    else if(rbDeviceMapping->Checked)                                           //Steven 20190910 : Qualcomm功能
    {
        iContactMode=CONTACT_DEVICE_MAP_CHECK;
        Memo1->Lines->Add("CONTACT_DEVICE_MAP_CHECK");
    }
    else if(rbAutoHeight->Checked)
    {
        iContactMode=CONTACT_AUTO_GET_HEIGHT;
        Memo1->Lines->Add("CONTACT_AUTO_GET_HEIGHT");
    }
    else if(rbManualHeight->Checked)
    {
        iContactMode=CONTACT_MANUAL_GET_HEIGHT;
        Memo1->Lines->Add("CONTACT_MANUAL_GET_HEIGHT");
    }
    else if(rbContactTest->Checked)
    {
        iContactMode=CONTACT_TEST;
        Memo1->Lines->Add("CONTACT_TEST");
        if(CUSTOMER_CODE==CC_KYEC_CHEN &&
           IniConfig.bA16ContactTestDropContact)                                //wei 20150831
        {
            ChangeContactMode(true);
        }
    }
    else if(rbAutoContactTest->Checked)
    {
        iContactMode=AUTO_CONTACT_TEST;
        Memo1->Lines->Add("AUTO_CONTACT_TEST");
    }
    else if(rbStepContactTest->Checked)                                         //Steven 20150811 : Step by Step Contact Test
    {
        iContactMode=STEP_CONTACT_TEST;
        Memo1->Lines->Add("STEP_CONTACT_TEST");
    }
    else if(rbLoadCellAutoHigh->Checked)                                        // Step by Step Contact Test
    {
        iContactMode=CONTACT_LoadCell_AUTO_GET_HEIGHT;                          //kevin 20190909 add Load cell AutoHigh
        Memo1->Lines->Add("CONTACT_LoadCell_AUTO_GET_HEIGHT");
    }
    else if(rbDeviceLoopTest->Checked)                                          //Ztex 2023.11.19 Add CONTACT_DEVICE_LOOP_TEST
    {
        iContactMode=CONTACT_DEVICE_LOOP_TEST;
        Memo1->Lines->Add("CONTACT_DEVICE_LOOP_TEST");
    }
    else if(rbKTempIndexMove->Checked)                                          //Ztex 2024.03.26 Add Contact Mode K Temperature
    {
        iContactMode=K_TEMP_INDEX_MOVE;
        Memo1->Lines->Add("K_Temp_Index_Move");
        chk_K_Temperature->Checked=true;
    }
    else if(rbVisualDetectionTest->Checked)                                     //Ifor 20260204 add: TFAMD 要求新增檢測流程
    {
        iContactMode=VISUAL_DETECTION_TEST;
        Memo1->Lines->Add("VISUAL_DETECTION_TEST");
    }

    if(CUSTOMER_CODE==CC_KYEC_LEE ||
       CUSTOMER_CODE==CC_KYEC_XILINX ||
       CUSTOMER_CODE==CC_MAXIM_THAILAND)
    {
        if(iContactMode==CONTACT_AUTO_GET_HEIGHT)
        {
            cbOneTouchAutoContactHight->Visible=true;
        }
        else
        {
            cbOneTouchAutoContactHight->Visible=false;
            cbOneTouchAutoContactHight->Checked=false;                          //Ifor 20220803 add 一鍵完成Auto Contact Hight
        }
    }
    else
    {
        cbOneTouchAutoContactHight->Visible=false;
        cbOneTouchAutoContactHight->Checked=false;                              //Ifor 20220803 add 一鍵完成Auto Contact Hight
    }

    if(iContactMode==STEP_CONTACT_TEST)
    {
        chkDailyCorrelation->Enabled=true;
    }
    else
    {
        chkDailyCorrelation->Enabled=false;
        chkDailyCorrelation->Checked=false;
    }
}
//---------------------------------------------------------------------------
void TfContact::ChangeContactMode(bool ret)                                     //Steven 20150224 : Auto Contact Test
{
    if(ret==true)
    {
        cbContactMode->ItemIndex=DropContact;
        cbVacuumMode->ItemIndex=VacuumOFFMode;
        edDropWaitTime->Text="0.5";
        edDropOffset1->Enabled=true;                                            //2012-01-03    Dell
        edDropOffset2->Enabled=true;                                            //2012-01-03    Dell
    }
    else
    {
        cbContactMode->ItemIndex=DirectContactMode;
        cbVacuumMode->ItemIndex=VacuumOFFMode;
        edDropWaitTime->Text="0.5";
        edDropOffset1->Enabled=false;                                           //2012-01-03    Dell
        edDropOffset2->Enabled=false;                                           //2012-01-03    Dell
    }
}
//---------------------------------------------------------------------------
TQPF_Timer AutoContactTestDelay;
//---------------------------------------------------------------------------
bool __fastcall TfContact::Do_AutoContactTest(bool bReset)                      //Steven 20150224 : Auto Contact Test
{
    static AnsiString ErrPart="";
    static int Pos1=0, Pos2=0, PosZ1Old=0, PosZ2Old=0;
    static int count=0;
    static bool bHasErrorBin=false;
    static bool flag1=false, flag2=false;

    int &Task=AutoContactTestTask;
    int iSiteOn[4]={0, 0, 0, 0}, iNN=IsNNMode();
    bool TMode=false;
    bool bResult=false;
    bool bSpecialCheck=false;                                                   //Ifor 20210815 add:非正常模式掉料檢測

    if(bReset)
    {
        Task=actInitial;
        return false;
    }

    switch(Task)
    {
        case actInitial:
            PosZ1Old=MOT[MTestZ1].Gali_ReadEncoderPos();
            PosZ2Old=MOT[MTestZ2].Gali_ReadEncoderPos();
            Pos1=Get0_01MMType(edContactHeight1->Text.c_str());
            Pos2=Get0_01MMType(edContactHeight2->Text.c_str());
            Prod.TestZ1_Test=Get0_01MMType(edContactHeight1->Text.c_str());
            Prod.TestZ2_Test=Get0_01MMType(edContactHeight2->Text.c_str());
            iBackUpZ1DownPosition=Pos1;
            iBackUpZ2DownPosition=Pos2;
            count=0;
            flag1=false;
            flag2=false;
            bHasErrorBin=false;
            Task=actArm2ToCenter;
            break;
        case actArm2ToCenter:                                                                                                                                   //先做Z1 Up Z2 Down
            if(MOT[MTestY1].GalilTwoY_Move(Prod.TestY1_Front, Prod.TestY2_Middle, GotIndexYSpeed(iSpeed*3000), __FUNC__))                                       //JimmyChiu 20211028 : All speed can set by speed setting.
            {
                Task=actArm2ZDown;
            }
            break;
        case actArm2ZDown:                                                                                              //把Arm 2先下降
            if(MOT[MTestZ2].Gali_MotMoveNoWait(Pos2, GotIndexZSpeed(iSpeedZ*1000), 0))                                  //JimmyChiu 20211028 : All speed can set by speed setting.
            {
                Task=actZ1DownZ2Up;
                SetMotorSpeed();
            }
            break;
        case actZ1DownZ2Up:                                                                                             //Arm1 下壓測試-------
            if(LastSet.iRealDummy==REALLY)
            {
                if(TestIF.iShuttleMode==1 && TestIF.iShuttle_Sel==0)                                                    //Ifor 20210815 add:非正常模式掉料檢測
                {
                    bSpecialCheck=true;
                }
                else if(IniConfig.bD58UseArm1PickPlaceArm2Test==true &&
                        TestIF_File.bArm1PickPlaceArm2Test==true)
                {
                    bSpecialCheck=true;
                }
                else
                {
                    bSpecialCheck=false;
                }

                if((MOT[MTestZ2].Gali_ReadPos()>(Prod.TestZ2_Test-Prod.TestZ2_Drop_Offset+500)) ||                      //jou 2011-08-16 +100 -> +500 drop mode容易造成誤判
                   bSpecialCheck==true                                                          )                       //2008/10/20 lee //Ifor 20210716 add:避免關ARM不偵測掉料
                {
                    flag1|=CheckIndexAllSuckICFallDown(true, false);
                    flag2|=CheckIndexAllSuckICFallDown(false, true);

                    if(flag1 || flag2)
                    {
                        MOT[MTestZ1].Gali_Command("ST", __FUNC__);
                        Task=actDropICMoveZ;
                        break;
                    }
                }
            }

            if(DeviceForm.ContactMode==TMove ||
               DeviceForm.ContactMode==TMoveDrop ||                                                                     //jou 2012-02-03 新增T Move Drop
               DeviceForm.ContactMode==TMoveDropSlowContact ||
               DeviceForm.ContactMode==TMoveSlowContact)                                                                //Steven 20160130 : TMove Soft contact
                TMode=true;
            else
                TMode=false;

            #ifdef INDEX_PROTECT_TMOVE
            if(bOverRangeDoTMode==true && bTriger4Indexhome==false)                                                     //Isaac 20201012 : index Y超過範圍，做一次Tmode
            {
                bTriger4Indexhome=true;
                bOverRange4Indexhome=true;

                TrigerIndexAxisHome();                                                                                  //Isaac 20201012 : index Y超過範圍，做一次Tmode，初始化，開始自動校正

                return false;
            }
            #endif

            if(MOT[MTestY1].Z1DownZ2Up(MOT[MTestZ1].GailSpeed,TMode,false))
            {
                fMain->SendMSG_CMD(MSG_CMD_ContactTestArm1);                                                            //Steven 20150304 : Add GPIB LOG //Ifor 20180605 (wei) MSG_CMD_ContactTestArm2 => MSG_CMD_ContactTestArm1
                flag1=false;
                flag2=false;
                Task=actStartDelayTimeArm1;
                AutoContactTestDelay.SetSecAndOn(Prod.dTesterStartDelayTime);
            }
            break;
        case actStartDelayTimeArm1:
            if(AutoContactTestDelay.Off())
            {
                if(TestIF.iShuttleMode==1)                                      //Use Signal shuttle
                {
                    if(TestIF.iShuttle_Sel==0)                                  //shuttle 1
                    {
                        Task=actZ1UpZ2Down;
                        break;
                    }
                }

                if(CUSTOMER_CODE==CC_TSMC_TAINAN &&
                   (count<atoi(edAutoContactTest->Text.c_str())-1 ||            //wei 20160329 TSMC Auto Contact Test 最後一次才測試
                    LastSet.iTester==OFF_LINE))                                 //wei 20160413 offline不送訊號
                {
                    Task=actArmMoveCount1;
                }
                else
                {
                    Task=actSOTArm1;
                }
            }
            break;
        case actSOTArm1:
            fTestCategory->BringToFront();                                      //Steven 20100823
            if(IniConfig.bC04EnableTestTempIC)
                fDynamicTemp->BringToFront();                                   //Steven 20120810
            iSetupTask=1;
            IsTest=true;                                                        //Steven 20110920
            Task=actGetTestResult1;
            break;
        case actGetTestResult1:
            if(DoSetupTest(0))
            {
                bHasErrorBin=false;
                for(int i=0; i<TestSocket.iShtRow; i++)
                {
                    for(int j=0; j<TestSocket.iShtCol; j++)
                    {
                        if(TestSocket.Item[i][j]!=NULL_IC &&
                           TestSocket.Item[i][j]!=HAS_NULL_IC)
                        {
                            if(TestSocket.bPass[i][j]==false)
                            {
                                bHasErrorBin=true;
                                Task=actGetHome;
                                break;
                            }
                        }
                    }
                }

                Task=actArmMoveCount1;
                break;
            }
            break;
        case actArmMoveCount1:
            count++;
            Memo1->Lines->Add("Auto Contact Test Count : "+AnsiString(count));
            if(count>=atoi(edAutoContactTest->Text.c_str()))
            {
                Task=actGetHome;
            }
            else
            {
                Task=actZ1UpZ2Down;
            }
            break;
        case actZ1UpZ2Down:                                                                                             //Arm2 下壓測試-------
            if(LastSet.iRealDummy==REALLY)
            {
                if(TestIF.iShuttleMode==1 && TestIF.iShuttle_Sel==1)                                                    //Ifor 20210815 add:非正常模式掉料檢測
                {
                    bSpecialCheck=true;
                }
                else if(IniConfig.bD58UseArm1PickPlaceArm2Test==true &&
                        TestIF_File.bArm1PickPlaceArm2Test==true)
                {
                    bSpecialCheck=true;
                }
                else
                {
                    bSpecialCheck=false;
                }

                if((MOT[MTestZ1].Gali_ReadPos()>(Prod.TestZ1_Test-Prod.TestZ1_Drop_Offset+500)) ||
                    bSpecialCheck==true                                                          )                      //2008/10/20 lee //Ifor 20210716 add:避免關ARM不偵測掉料
                {
                    flag1|=CheckIndexAllSuckICFallDown(true, false);
                    flag2|=CheckIndexAllSuckICFallDown(false, true);

                    if(flag1 || flag2)
                    {
                        MOT[MTestZ1].Gali_Command("ST", __FUNC__);
                        Task=actDropICMoveZ;
                        break;
                    }
                }
            }

            if(DeviceForm.ContactMode==TMove ||
               DeviceForm.ContactMode==TMoveDrop ||                                                                     //jou 2012-02-03 新增T Move Drop
               DeviceForm.ContactMode==TMoveDropSlowContact ||
               DeviceForm.ContactMode==TMoveSlowContact)                                                                //Steven 20160130 : TMove Soft contact
                TMode=true;
            else
                TMode=false;

            #ifdef INDEX_PROTECT_TMOVE
            if(bOverRangeDoTMode==true && bTriger4Indexhome==false)                                                     //Isaac 20201012 : index Y超過範圍，做一次Tmode
            {
                bTriger4Indexhome=true;
                bOverRange4Indexhome=true;
                TrigerIndexAxisHome();                                                                                  //Isaac 20201012 : index Y超過範圍，做一次Tmode，初始化，開始自動校正
                return false;
            }
            #endif

            if(MOT[MTestY1].Z1UpZ2Down(MOT[MTestZ2].GailSpeed, TMode, false))
            {
                fMain->SendMSG_CMD(MSG_CMD_ContactTestArm2);                                                            //Steven 20150304 : Add GPIB LOG //Ifor 20180605 (wei) MSG_CMD_ContactTestArm1 => MSG_CMD_ContactTestArm2
                flag1=false;
                flag2=false;
                Task=actStartDelayTimeArm2;
                AutoContactTestDelay.SetSecAndOn(Prod.dTesterStartDelayTime);
            }
            break;
        case actStartDelayTimeArm2:
            if(AutoContactTestDelay.Off())
            {
                if(TestIF.iShuttleMode==1)                                      //Use Signal shuttle
                {
                    if(TestIF.iShuttle_Sel==0)                                  //shuttle 1
                    {
                        Task=actZ1DownZ2Up;
                        break;
                    }
                }

                if(CUSTOMER_CODE==CC_TSMC_TAINAN &&
                   (count<atoi(edAutoContactTest->Text.c_str())-1 ||            //wei 20160329 TSMC Auto Contact Test 最後一次才測試
                    LastSet.iTester==OFF_LINE))                                 //wei 20160413 offline不送訊號
                    Task=actArmMoveCount2;
                else
                    Task=actSOTArm2;
            }
            break;
        case actSOTArm2:
            fTestCategory->BringToFront();                                      //Steven 20100823
            if(IniConfig.bC04EnableTestTempIC)
                fDynamicTemp->BringToFront();                                   //Steven 20120810
            iSetupTask=1;
            IsTest=true;                                                        //Steven 20110920
            Task=actGetTestResult2;
            break;
        case actGetTestResult2:
            if(DoSetupTest(1))
            {
                bHasErrorBin=false;
                for(int i=0; i<TestSocket.iShtRow; i++)
                {
                    for(int j=0; j<TestSocket.iShtCol; j++)
                    {
                        if(TestSocket.Item[i][j]!=NULL_IC && TestSocket.Item[i][j]!=HAS_NULL_IC)
                        {
                            if(TestSocket.bPass[i][j]==false)
                            {
                                bHasErrorBin=true;
                                Task=actGetHome;
                                break;
                            }
                        }
                    }
                }

                Task=actArmMoveCount2;
                break;
            }
            break;
        case actArmMoveCount2:
            count++;
            Memo1->Lines->Add("Auto Contact Test Count : "+AnsiString(count));
            if(count>=atoi(edAutoContactTest->Text.c_str()))
            {
                Task=actGetHome;
            }
            else
            {
                Task=actZ1DownZ2Up;
            }
            break;
        case actDropICMoveZ:                                                                                            //掉料處理------
            if(MOT[MTestZ1].Gali_Two_ZAxis_Move(Prod.TestZ1_Safe, GotIndexZSpeed(iSpeedZ*1000), __FUNC__))              //先把Z軸移上來   //JimmyChiu 20211028 : All speed can set by speed setting.
            {
                Memo1->Lines->Add("Auto Contact Test IC Drop Fail.");
                Task=actDropICMoveY;
            }
            break;
        case actDropICMoveY:
            if(MOT[MTestY1].GalilTwoY_Move(Prod.TestY1_Front, Prod.TestY2_Rear, GotIndexYSpeed(iSpeed*3000), __FUNC__))                                         //JimmyChiu 20211028 : All speed can set by speed setting.
            {
                Task=actDropICAlarm;
            }
            break;
        case actDropICAlarm:
            if(CosFunction.bJAM0303NeedOpenChamberDoor)                         //Steven : JAM0303 & JAM0403需要開啟Chamber門10秒
                bIsTestSitICFallDown=true;

            if(flag1)
            {
                ErrPart="";
                for(int i=0; i<FTestSuck.iShtRow; i++)
                {
                    for(int j=0; j<FTestSuck.iShtCol; j++)
                    {
                        if(FTestSuck.Suck[i][j].Enable       &&
                           FTestSuck.Suck[i][j].SenUsing!="" &&
                           FTestSuck.Item[i][j]!=HAS_NULL_IC &&
                           FTestSuck.Item[i][j]!=NULL_IC)
                        {
                            if(FTestSuck.Suck[i][j].GetStatus()==false)
                            {
                                ErrPart+=IndexSuckName[i+iNN][j];
                            }
                        }
                    }
                }
                ShowErrorMessage("JAM0303", K_SKIP, MTestZ1, false, ErrPart);
            }

            if(flag1==false && flag2)
            {
                ErrPart="";
                for(int i=0; i<BTestSuck.iShtRow; i++)
                {
                    for(int j=0; j<BTestSuck.iShtCol; j++)
                    {
                        if(BTestSuck.Suck[i][j].Enable       &&
                           BTestSuck.Suck[i][j].SenUsing!="" &&
                           BTestSuck.Item[i][j]!=HAS_NULL_IC &&
                           BTestSuck.Item[i][j]!=NULL_IC)
                        {
                            if(BTestSuck.Suck[i][j].GetStatus()==false)
                            {
                                ErrPart+=IndexSuckName[i][j];
                            }
                        }
                    }
                }
                ShowErrorMessage("JAM0304", K_SKIP, MTestZ2, false, ErrPart);
            }
            Task=actFinish;
        case actGetHome:                                                                                                //做完上升並分開------
            if(MOT[MTestZ1].Gali_Two_ZAxis_Move(Prod.TestZ1_Safe, GotIndexZSpeed(iSpeedZ*1000), __FUNC__))              //先把Z軸移上來      //JimmyChiu 20211028 : All speed can set by speed setting.
            {
                Task=actArmOpen;
            }
            break;
        case actArmOpen:
            if(MOT[MTestY1].GalilTwoY_Move(Prod.TestY1_Front, Prod.TestY2_Rear, GotIndexYSpeed(iSpeed*3000), __FUNC__))                                         //JimmyChiu 20211028 : All speed can set by speed setting.
            {
                if(bHasErrorBin==true)
                {
                    Memo1->Lines->Add("Auto contact test detect error bin, abort procedure.");
                    Task=actHasErrorBin;
                }
                else
                {
                    Memo1->Lines->Add("Auto Contact Test Finish.");
                    Task=actFinish;
                }
            }
            break;
        case actHasErrorBin:                                                    //偵測到Error Bin Alarm-----
            ShowErrorMessage("WAR0311", K_SKIP, MMIndex, false, "");
            Task=actFinish;
            break;
        case actFinish:                                                         //結束流程------
            IsTest=false;
            TestSocket.ClearAll();
            if(ATC_InterfaceForm->iATC_MODE_TYPE==ATC_TYPE_70 &&
               Temperature.bATC7TSDFunction==true)                              //Steven 20161201 : by site TSD for Contact Test
            {
                iSiteOn[0]=0;
                iSiteOn[1]=0;
                iSiteOn[2]=0;
                iSiteOn[3]=0;
                ATC_InterfaceForm->UseTSD_Function(4, iSiteOn);
            }

            if(TestIF.iGpibMode==InterfaceType_SPEA_Type)
            {
                bool flag[32]={false};
                if(BAR_CODE_INSTALL!=ebctUninstall && TestIF_File.bEnableBarCode)
                    _RunTestProgram_BarMess(sizeof(flag), flag, 0, "");
                else
                    _RunTestProgram(sizeof(flag), flag);
            }
            else
            {
                fMain->RunTestProgram(false);
            }
            bResult=true;
            break;
    }
    return bResult;
}
//---------------------------------------------------------------------------
bool __fastcall TfContact::DoStepContactLoadDevice(bool Reset)                  //Steven 20150811 : Step by Step Contact Test
{
    static int iSht=0, iLoaderX=0, iLoaderY=0, iShuttleX=0, iShuttleY=0;
    static int iStep=0;

    int &Task=StepContactTestLoadTask;
    int iXPos=0, iYPos=0, ret=0;
    int iXVariable[X_PITCH_COUNT];
    int iYVariable  =0;
    int iMovePitchX =9000;
    int iMovePitchY =6000;
    int iZPos[MAX_ARM_Row][MAX_ARM_Col];
    int iOffsetPos=-1, iNN=IsNNMode();
    bool flag=false;
    bool bZFlag[MAX_ARM_Row][MAX_ARM_Col];
    bool bResult=false, bHasICToPick=false, bHasPocketToPut=false;
    AnsiString Str;

    ZeroMemory(iXVariable, sizeof(iXVariable));
    ZeroMemory(bZFlag, sizeof(bZFlag));
    ZeroMemory(iZPos, sizeof(iZPos));

    if(Reset)
    {
        iStep=-1;
        iSht=-1;
        Task=sctlInit;
        return bResult;
    }

    switch(Task)
    {
        case sctlInit:
            if(iContactMode==CONTACT_DEVICE_MAP_CHECK)                          //Steven 20191009 : Device Map for Qualcomm
            {
                if(LastSet.iLanguageCountry==1)
                {
                    Memo1->Lines->Add("從Loader吸取IC");
                }
                else
                {
                    Memo1->Lines->Add("Loading IC from Loader.");
                }
            }
            else
            {
                if(LastSet.iLanguageCountry==1)
                {
                    Memo1->Lines->Add("請放IC到Loader上, 並按下Setp繼續下一步");
                }
                else
                {
                    Memo1->Lines->Add("Please put tray on loader, and push 'STEP' for next step.");
                }
            }
            Task=sctlStep1;
            break;
        case sctlStep1:
            if(MOT[MMTrayY].HasIC())                                            //Steven 20191009 : Device Map for Qualcomm
            {
                Task=sctlEditTray;
            }
            else if(iContactMode==CONTACT_DEVICE_MAP_CHECK ||                   //Steven 20191009 : Device Map for Qualcomm
                    WaitManualStepKey())
            {
                if(LastSet.iLanguageCountry==1)
                {
                    Memo1->Lines->Add("入Tray至Loader工作區");
                }
                else
                {
                    Memo1->Lines->Add("Loading tray to handler.");
                }
                InitLoadTask();
                Task=sctlLoadTray;
            }
            break;
        case sctlLoadTray:
            DoLoad();
            if(LoadTask==1 && MOT[MMTrayY].HasIC())
            {
                if(TestIF_File.bEnableDeviceRemain)                             //wei 20171128
                {
                    bResult=true;
                    break;
                }
                else
                {
                    Task=sctlEditTray;
                }
            }
            break;
        case sctlEditTray:
            if(iContactMode==CONTACT_DEVICE_MAP_CHECK)                          //Steven 20191009 : Device Map for Qualcomm
            {
                if(CosFunction.bDeviceMapTestPandP)
                {
                    if(dmp_RICHTEK.TransformRICHTEKMap()==true)
                    {
                        ShowMSG(AnsiString().sprintf("Run Device map from id %d",dmp_RICHTEK.iNowDevicePos+1));
                    }
                    else                                                        //finish
                    {
                        bResult=true;
                        break;
                    }
                }
                else
                {
                    TransformDMCMap();                                          //Steven 20220510 : For QTI SD Device Map Function
                }
            }
            else
            {
                if(LastSet.iLanguageCountry==1)
                {
                    Memo1->Lines->Add("請編輯Tray盤資料, 完成後請按下STEP繼續下一步");
                }
                else
                {
                    Memo1->Lines->Add("Please edit devices data on loader tray. And push STEP for next step");
                }

                MOT[MMTrayY].InitEmptyTray(__FUNC__);                           //Steven 20151215 : 在load tray後會自動出現loader tray編輯,但須人工方式將tray內所有的產品經由編輯把它全數清除後,才可進行選擇arm1 or arm2須入料幾顆產品."客戶要求一入料出現tray編輯時自動全數清空"
                btEditTray->Visible=true;
                EditTray(MMTrayY, 1);
            }
            Task=sctlEditTrayOK;
            break;
        case sctlEditTrayOK:
            if(iContactMode==CONTACT_DEVICE_MAP_CHECK ||                        //Steven 20191009 : Device Map for Qualcomm
               WaitManualStepKey())
            {
                if(LastSet.iLanguageCountry==1)
                {
                    Memo1->Lines->Add("入料至Shuttle");
                }
                else
                {
                    Memo1->Lines->Add("Loading devices to shuttle.");
                }
                Task=sctlFindICOnLoad;

                for(int i=0; i<FTestSuck.iShtRow; i++)
                {
                    for(int j=0; j<FTestSuck.iShtCol; j++)
                    {
                        if(LastSet.bUseTestSocket[0][i+iNN][j]==false)
                        {
                            FLCarryKit.SetItemData(i, j, HAS_NULL_IC);
                        }

                        if(LastSet.bUseTestSocket[1][i][j]==false)              //Mylin 20220606 Debug In Arm Hang Up When Place IC to Shuttle ==>
                        {
                            BLCarryKit.SetItemData(i, j, HAS_NULL_IC);
                        }
                    }
                }
            }
            break;
        case sctlFindICOnLoad:
            bHasICToPick=false;
            bHasPocketToPut=false;
            iSht=-1;
            if(iContactMode==CONTACT_DEVICE_MAP_CHECK)                          //Steven 20191009 : Device Map for Qualcomm
            {
                iSht=iDMCArm-1;
                iStep++;
                if(TestIF_File.iTestMode==DualSite ||
                   TestIF_File.iTestMode==QualSite2X2 ||
                   TestIF_File.iTestMode==_8Site2X4 ||
                   TestIF_File.iTestMode==QualSite1X4)                          //Steven 20220510 : For QTI SD Device Map Function
                {
                    InArmSuck.iWhichShtPickFor32=iSht;
                    InitArmPickFromLoadStageTask();
                    if(iStep>=2)
                        bResult=true;
                }
                else
                {
                    if(iStep>=TestSocket.iShtCnt)
                    {
                        if(iSht==0)
                            FLCarryKit.SetNullIcToHasNullIc();
                        else
                            BLCarryKit.SetNullIcToHasNullIc();
                        bResult=true;
                    }

                    if(iDMCChannel[iStep]<0 || iDMCTrayX[iStep]<0 || iDMCTrayY[iStep]<0)
                    {
                        break;
                    }
                    else
                    {
                        iLoaderX=iDMCTrayX[iStep];                              //Steven 20210806 : Fixed for Device Mapping
                        iLoaderY=iDMCTrayY[iStep];
                        iShuttleX=-1;
                        iShuttleY=-1;

                        for(int i=0; i<TestSocket.iShtRow; i++)
                        {
                            for(int j=0; j<TestSocket.iShtCol; j++)
                            {
                                if(iDMCChannel[iStep]==TestIF_File.iSiteMap[i][j])
                                {
                                    iShuttleX=j;
                                    iShuttleY=i;
                                }
                            }
                        }

                        if(iLoaderX==-1 || iLoaderY==-1 || iShuttleX==-1 || iShuttleY==-1)
                        {
                            break;
                        }
                        else
                        {
                            Str.sprintf("Load IC from Tray X:%d, Y:%d to shuttle X:%d, Y:%d", iLoaderX, iLoaderY, iShuttleX, iShuttleY);
                            Memo1->Lines->Add(Str);
                        }
                    }
                }
            }
            else
            {
                for(int i=0; i<InArmSuck.iShtRow; i++)
                {
                    for(int j=0; j<InArmSuck.iShtCol; j++)
                    {
                        if(bHasPocketToPut==false && FLCarryKit.Item[i][j]==NULL_IC)
                        {
                            bHasPocketToPut=true;
                            iSht=0;
                            iShuttleX=j;
                            iShuttleY=i;
                        }
                    }
                }

                if(iSht!=0)
                {
                    for(int i=0; i<InArmSuck.iShtRow; i++)
                    {
                        for(int j=0; j<InArmSuck.iShtCol; j++)
                        {
                            if(bHasPocketToPut==false && BLCarryKit.Item[i][j]==NULL_IC)
                            {
                                bHasPocketToPut=true;
                                iSht=1;
                                iShuttleX=j;
                                iShuttleY=i;
                            }
                        }
                    }
                }

                if(iSht==0)
                {
                    for(int j=0; j<MOT[MMTrayY].Tray.YItem; j++)
                    {
                        for(int i=0; i<MOT[MMTrayY].Tray.XItem; i++)
                        {
                            if(bHasICToPick==false && MOT[MMTrayY].Tray.Data[i][j]==HAS_IC)
                            {
                                iLoaderX=i;
                                iLoaderY=j;
                                bHasICToPick=true;
                            }
                        }
                    }

                    if(bHasICToPick==false)
                    {
                        FLCarryKit.SetNullIcToHasNullIc();
                        break;
                    }
                }
                else if(iSht==1)
                {
                    for(int j=0; j<MOT[MMTrayY].Tray.YItem; j++)
                    {
                        for(int i=0; i<MOT[MMTrayY].Tray.XItem; i++)
                        {
                            if(bHasICToPick==false && MOT[MMTrayY].Tray.Data[i][j]==HAS_HOT_IC)
                            {
                                iLoaderX=i;
                                iLoaderY=j;
                                bHasICToPick=true;
                            }
                        }
                    }

                    if(bHasICToPick==false)
                    {
                        BLCarryKit.SetNullIcToHasNullIc();
                        break;
                    }
                }
                else
                {
                    bResult=true;
                    break;
                }
            }
            Task=sctlInXYToLoad;
            break;
        case sctlInXYToLoad:
            if(iContactMode==CONTACT_DEVICE_MAP_CHECK &&
               (TestIF_File.iTestMode==DualSite ||
                TestIF_File.iTestMode==QualSite2X2 ||
                TestIF_File.iTestMode==_8Site2X4 ||
                TestIF_File.iTestMode==QualSite1X4))                            //Steven 20220510 : For QTI SD Device Map Function
            {
                flag=DoInArmPickFromLoadStage_9045();
                if(flag)
                {
                    InitInArmPlaceToShuttleTask();
                    Task=sctlInXYToShuttle;
                }
            }
            else
            {
                iMovePitchX=iXpitchMaxX3;
                iMovePitchY=AutoCalculateInArmYClosePitch();
                iYVariable=GetInArmPitchY_9045(iMovePitchY, iOffsetPos);
                for(int i=0; i<X_PITCH_COUNT; i++)
                    iXVariable[i]=GetInArmPitchX_9045(iMovePitchX, i, iOffsetPos);

                iXPos=Prod.XInArm_Tray_Pick[0][3]+iLoaderX*Prod.LoadForm.iXPitch-iMovePitchX/3;
                iYPos=Prod.YInArm_Tray_Pick[0][3]-iLoaderY*Prod.LoadForm.iYPitch;

                if(USE_IN_Y_IS_AUTO_PITCH==true)                                //Steven 20210806 : Fixed for Device Mapping  //JerryYang 20251218 : IN/OUT ARM支援不同模組
                    iYPos-=iMovePitchY;

                if(InArmContinuousMove_9045(iXPos, iYPos, iXVariable, iYVariable, bZFlag, iZPos, false))
                {
                    Task=sctlInZToLoadPick;
                }
            }
            break;
        case sctlInZToLoadPick:
            if(MOT[MInArmZG].MotorMove2SpeedForPicker(Prod.ZInArm_Tray_Pick[0][3], &ArmSpeed[InArm]))                   //Steven 20210806 : Fixed for Device Mapping (ZG)
            {
                InArmSuck.Suck[0][3].Reset();
                Task=sctlInLoadPick;
            }
            break;
        case sctlInLoadPick:
            if(InArmSuck.Suck[0][3].Suck())
            {
                if(iSht==0)
                    MOT[MMTrayY].SetTraySingleData(iLoaderX, iLoaderY, HAS_NULL_IC);
                else
                    MOT[MMTrayY].SetTraySingleData(iLoaderX, iLoaderY, HAS_NULL_CLEAN_IC);                              //為了放回原處,應該要記錄IC的XY
                InArmSuck.SetItemData(0, 3, HAS_IC);
                Task=sctlInZLoadUp;
            }
            else if(InArmSuck.Suck[0][3].Error)                                                                         //少了例外處理
            {
                Task=sctlInLoadPickErrZUp;
            }
            break;
        case sctlInLoadPickErrZUp:
            if(MOT[MInArmZG].MotorMove(0))                                      //Steven 20210806 : Fixed for Device Mapping (ZG)
            {
                Task=sctlInLoadPickErrAlarm;
            }
            break;
        case sctlInLoadPickErrAlarm:
            ret=ShowErrorMessage("MES0101", K_RETRY|K_SKIP, MInArmX, false, "G");                                       //Steven 20210806 : Fixed for Device Mapping (ZG)
            InArmSuck.Suck[0][3].Reset();
            if(ret==K_SKIP)
            {
                MOT[MMTrayY].SetTraySingleData(iLoaderX, iLoaderY, NULL_IC);
                Task=sctlFindICOnLoad;
            }
            else
            {
                Task=sctlInXYToLoad;
            }
            break;
        case sctlInZLoadUp:
            if(MOT[MInArmZG].MotorMove(0))                                      //Steven 20210806 : Fixed for Device Mapping (ZG)
            {
                InArmSuck.Suck[0][3].Reset();
                Task=sctlInXYToShuttle;
                InitInArmPlaceToShuttleTask();                                  //kevin 20180309 add

                if(BOTTOM_2DID && TestIF_File.bEnableBottom2D==true)            //Steven 20190308 : Bottom 2D
                {
                    Task=sctlBottom2DInit;
                }
            }
            break;
        case sctlBottom2DInit:                                                  //Steven 20190308 : Bottom 2D
            fBarCode->InitBottom2DIDScan();
            Task=sctlBottom2DScan;
        case sctlBottom2DScan:
            flag=fBarCode->DoBottom2DIDScan();
            if(flag)
            {
                Task=sctlInXYToShuttle;
                InArmSuck.Suck[0][3].Reset();
                Task=sctlInXYToShuttle;
                InitInArmPlaceToShuttleTask();                                  //kevin 20180309 add
            }
            break;
        case sctlInXYToShuttle:
            if(iContactMode==CONTACT_DEVICE_MAP_CHECK &&
               (TestIF_File.iTestMode==DualSite ||
                TestIF_File.iTestMode==QualSite2X2 ||
                TestIF_File.iTestMode==_8Site2X4 ||
                TestIF_File.iTestMode==QualSite1X4))                            //Steven 20220510 : For QTI SD Device Map Function
            {
                flag=DoInArmPlaceToShuttle_9045();
                if(flag)
                {
                    bResult=true;
                }
            }
            else
            {
                iMovePitchX=iXpitchMaxX3;
                iMovePitchY=AutoCalculateInArmYClosePitch();
                iYVariable=GetInArmPitchY_9045(iMovePitchY, iOffsetPos);
                for(int i=0; i<X_PITCH_COUNT; i++)
                    iXVariable[i]=GetInArmPitchX_9045(iMovePitchX, i, iOffsetPos);

                if(iSht==0)
                {
                    iXPos=Prod.XInArm_Shuttle1_Place[iInArmYBase][iInArmXBase];
                    iYPos=Prod.YInArm_Shuttle1_Place[iInArmYBase][iInArmXBase];
                }
                else
                {
                    iXPos=Prod.XInArm_Shuttle2_Place[iInArmYBase][iInArmXBase];
                    iYPos=Prod.YInArm_Shuttle2_Place[iInArmYBase][iInArmXBase];
                }

                if(TestIF.iTestMode==_6Site2X3)
                    iXPos=iXPos-TestIF.dSiteXPitch;                             //wei 20151228 Step Contact 2X3移動位置問題修正
                else
                    iXPos=iXPos+iInArmShtXCenterPos-iMovePitchX/3;              //先移動到Kit中間, 對齊第四支吸嘴, 所以要左移一個位置
                iYPos+=iInArmShtYCenterPos;

                if(iShuttleY==0)                                                //根據不同模式,需要修正
                    iYPos=iYPos+TestIF.dSiteYPitch/2;
                else
                    iYPos=iYPos-TestIF.dSiteYPitch/2;

                if(USE_IN_Y_IS_AUTO_PITCH==true)                                //JerryYang 20251218 : IN/OUT ARM支援不同模組
                    iYPos-=iMovePitchY;

                switch(TestIF.iTestMode)                                        //Steven 20151215 : 新增模式for Step Contact
                {
                    case SingleSite:
                    case DualSite2x1:
                        break;
                    case DualSite:
                    case QualSite2X2:
                        if(iShuttleX==0)
                            iXPos=iXPos-TestIF.dSiteXPitch/2;
                        else
                            iXPos=iXPos+TestIF.dSiteXPitch/2;
                        break;
                    case QualSite1X4:                                           //不支援偏心Kit!!
                    case _8Site2X4:
                        if(iShuttleX==0)
                            iXPos=iXPos-TestIF.dSiteXPitch-TestIF.dSiteXPitch/2;
                        else if(iShuttleX==1)
                            iXPos=iXPos-TestIF.dSiteXPitch/2;
                        else if(iShuttleX==2)
                            iXPos=iXPos+TestIF.dSiteXPitch/2;
                        else
                            iXPos=iXPos+TestIF.dSiteXPitch+TestIF.dSiteXPitch/2;
                        break;
                    case _6Site2X3:
                        if(iShuttleX==0)
                            iXPos=iXPos-TestIF.dSiteXPitch;
                        else if(iShuttleX==2)                                   //可能會行程不足
                            iXPos=iXPos+TestIF.dSiteXPitch;
                        break;
                }

                if(InArmContinuousMove_9045(iXPos, iYPos, iXVariable, iYVariable, bZFlag, iZPos, false))
                {
                    Task=sctlInZShuttlePut;
                }
            }
            break;
        case sctlInZShuttlePut:
            if(iSht==0)
                flag=MOT[MInArmZG].MotorMove2SpeedForPicker(Prod.ZInArm_Shuttle1_Place[0][3], &ArmSpeed[InArm]);
            else
                flag=MOT[MInArmZG].MotorMove2SpeedForPicker(Prod.ZInArm_Shuttle2_Place[0][3], &ArmSpeed[InArm]);

            if(flag)
            {
                InArmSuck.Suck[0][3].Reset();
                Task=sctlInShuttlePut;
            }
            break;
        case sctlInShuttlePut:
            if(InArmSuck.Suck[0][3].Destroy() || InArmSuck.Suck[0][3].Error)    //暫時不管IC掉落
            {
                if(iSht==0)
                    FLCarryKit.MoveSuckDataDiff(InArmSuck, 0, 3, iShuttleY, iShuttleX);
                else
                    BLCarryKit.MoveSuckDataDiff(InArmSuck, 0, 3, iShuttleY, iShuttleX);
                InArmSuck.SetItemData(0, 3, NULL_IC);
                bInArmCheckDestroyACT[0][3]=true;                               //JerryYang 20221118 : add
                Task=sctlInZShutleUp;
            }
//            else if(InArmSuck.Suck[0][3].Error)
//            {
//
//            }
            break;
        case sctlInZShutleUp:
            if(MOT[MInArmZG].MotorMove(0))                                      //Steven 20210806 : Fixed for Device Mapping (ZG)
            {
                Task=sctlFindICOnLoad;
            }
            break;
    }
    return bResult;
}
//---------------------------------------------------------------------------
bool __fastcall TfContact::DoStepContactUnloadDevice(bool Reset)                //Steven 20150811 : Step by Step Contact Test
{
    static int iArmRow=0, iArmCol=3;
    static int iSht, iLoaderX, iLoaderY, iShuttleX, iShuttleY;

    int &Task=StepContactTestUnloadTask;
    int iXPos=0, iYPos=0, ret=0;
    int iXVariable[X_PITCH_COUNT];
    int iYVariable  =0;
    int iMovePitchX =9000;
    int iMovePitchY =6000;
    int iOffsetPos  =-1;
    int iZPos[MAX_ARM_Row][MAX_ARM_Col];
    bool bZFlag[MAX_ARM_Row][MAX_ARM_Col];
    bool bResult=false, bHasICToPlace=false, bHasPocketToPick=false;
    bool flag=false;
    ZeroMemory(iXVariable, sizeof(iXVariable));
    ZeroMemory(bZFlag, sizeof(bZFlag));
    ZeroMemory(iZPos, sizeof(iZPos));

    if(Reset)
    {
        Task=sctuInit;
        return bResult;
    }

    switch(Task)
    {
        case sctuInit:
            bHasPocketToPick=false;
            iSht=-1;
            FLCarryKit.SetHasNullIcToNullIc();                                  //Steven 20160524 : ADD SetHasNullIcToNullIc
            for(int i=0; i<FLCarryKit.iShtRow; i++)
            {
                for(int j=0; j<FLCarryKit.iShtCol; j++)
                {
                    if(bHasPocketToPick==false &&
                       FLCarryKit.Item[i][j]!=NULL_IC)
                    {
                        bHasPocketToPick=true;
                        iSht=0;
                        iShuttleX=j;
                        iShuttleY=i;
                    }
                }
            }

            if(iSht!=0)
            {
                BLCarryKit.SetHasNullIcToNullIc();                              //Steven 20160524 : ADD SetHasNullIcToNullIc
                for(int i=0; i<BLCarryKit.iShtRow; i++)
                {
                    for(int j=0; j<BLCarryKit.iShtCol; j++)
                    {
                        if(bHasPocketToPick==false &&
                           BLCarryKit.Item[i][j]!=NULL_IC)
                        {
                            bHasPocketToPick=true;
                            iSht=1;
                            iShuttleX=j;
                            iShuttleY=i;
                        }
                    }
                }
            }

            if(iContactMode==CONTACT_DEVICE_MAP_CHECK &&
               (TestIF_File.iTestMode==DualSite ||
                TestIF_File.iTestMode==QualSite2X2 ||
                TestIF_File.iTestMode==_8Site2X4 ||
                TestIF_File.iTestMode==QualSite1X4))                            //Steven 20220510 : For QTI SD Device Map Function
            {
                InitPickFromShuttleTask();
                if(iSht==0)
                    iShuttleRowKit=GetShuttleState(euShuttle1, bAutoPick);
                else
                    iShuttleRowKit=GetShuttleState(euShuttle2, bAutoPick);
            }

            if(bHasPocketToPick)
            {
                Task=sctuInXYToShuttle;
            }
            else
            {
                Task=sctuInXYAway;
            }
            break;
        case sctuInXYToShuttle:
            if(iContactMode==CONTACT_DEVICE_MAP_CHECK &&
               (TestIF_File.iTestMode==DualSite ||
                TestIF_File.iTestMode==QualSite2X2 ||
                TestIF_File.iTestMode==_8Site2X4 ||
                TestIF_File.iTestMode==QualSite1X4))                            //Steven 20220510 : For QTI SD Device Map Function
            {
                flag=DoPickFromShuttle((eWhichShuttle)iSht, iShuttleRowKit);
                if(flag)
                {
                    Task=sctuInZShutleUp;
                }
            }
            else
            {
                iMovePitchX=iXpitchMaxX3;                                       //Isaac 20171204 (Steven) : Xpitch40->50mm, 12000->iXpitchMaxX3
                iMovePitchY=AutoCalculateInArmYClosePitch();
                iYVariable=GetInArmPitchY_9045(iMovePitchY, iOffsetPos);
                for(int i=0; i<X_PITCH_COUNT; i++)
                    iXVariable[i]=GetInArmPitchX_9045(iMovePitchX, i, iOffsetPos);

                if(iSht==0)
                {
                    iXPos=Prod.XInArm_Shuttle1_Place[iInArmYBase][iInArmXBase];
                    iYPos=Prod.YInArm_Shuttle1_Place[iInArmYBase][iInArmXBase];
                }
                else
                {
                    iXPos=Prod.XInArm_Shuttle2_Place[iInArmYBase][iInArmXBase];
                    iYPos=Prod.YInArm_Shuttle2_Place[iInArmYBase][iInArmXBase];
                }

                if(TestIF.iTestMode==_6Site2X3)
                    iXPos=iXPos-TestIF.dSiteXPitch;                             //wei 20151228 Step Contact 2X3移動位置問題修正
                else
                    iXPos=iXPos+iInArmShtXCenterPos-iMovePitchX/3;              //先移動到Kit中間, 對齊第四支吸嘴, 所以要左移一個位置
                iYPos=iYPos+iInArmShtYCenterPos;

                if(iShuttleY==0)                                                //根據不同模式,需要修正
                    iYPos+=TestIF.dSiteYPitch/2;
                else
                    iYPos-=TestIF.dSiteYPitch/2;

                if(USE_IN_Y_IS_AUTO_PITCH==true)                                //Steven 20210806 : Fixed for Device Mapping  //JerryYang 20251218 : IN/OUT ARM支援不同模組
                    iYPos-=iMovePitchY;

                switch(TestIF.iTestMode)                                        //Steven 20151215 : 新增模式for Step Contact
                {
                    case SingleSite:
                    case DualSite2x1:
                        break;
                    case DualSite:
                    case QualSite2X2:
                        if(iShuttleX==0)
                            iXPos=iXPos-TestIF.dSiteXPitch/2;
                        else
                            iXPos=iXPos+TestIF.dSiteXPitch/2;
                        break;
                    case QualSite1X4:                                           //不支援偏心Kit!!
                    case _8Site2X4:
                        if(iShuttleX==0)
                            iXPos=iXPos-TestIF.dSiteXPitch-TestIF.dSiteXPitch/2;
                        else if(iShuttleX==1)
                            iXPos=iXPos-TestIF.dSiteXPitch/2;
                        else if(iShuttleX==2)                                   //可能會行程不足
                            iXPos=iXPos+TestIF.dSiteXPitch/2;
                        else
                            iXPos=iXPos+TestIF.dSiteXPitch+TestIF.dSiteXPitch/2;
                        break;
                    case _6Site2X3:
                        if(iShuttleX==0)
                            iXPos=iXPos-TestIF.dSiteXPitch;
                        else if(iShuttleX==2)                                   //可能會行程不足
                            iXPos=iXPos+TestIF.dSiteXPitch;
                        break;
                }

                if(InArmContinuousMove_9045(iXPos, iYPos, iXVariable, iYVariable, bZFlag, iZPos, false))
                {
                    Task=sctuInZToShuttlePick;
                }
            }
            break;
        case sctuInZToShuttlePick:
            if(iSht==0)
                flag=MOT[MInArmZG].MotorMove2SpeedForPicker(Prod.ZInArm_Shuttle1_Place[0][3]+atof(edShtPickOffset1->Text.c_str())*100, &ArmSpeed[InArm]);       //Steven 20210806 : Fixed for Device Mapping (ZG)
            else
                flag=MOT[MInArmZG].MotorMove2SpeedForPicker(Prod.ZInArm_Shuttle2_Place[0][3]+atof(edShtPickOffset2->Text.c_str())*100, &ArmSpeed[InArm]);

            if(flag)
            {
                InArmSuck.Suck[0][3].Reset();
                Task=sctuInShuttlePick;
            }
            break;
        case sctuInShuttlePick:
            if(InArmSuck.Suck[0][3].Suck())
            {
                if(iSht==0)
                    InArmSuck.MoveSuckDataDiff(FLCarryKit, iShuttleY, iShuttleX, 0, 3);
                else
                    InArmSuck.MoveSuckDataDiff(BLCarryKit, iShuttleY, iShuttleX, 0, 3);

                Task=sctuInZShutleUp;
            }
            else if(InArmSuck.Suck[0][3].Error)
            {
                Task=sctuInShuttlePickErrZUp;
            }
            break;
        case sctuInShuttlePickErrZUp:
            if(MOT[MInArmZG].MotorMove(0))                                      //Steven 20210806 : Fixed for Device Mapping (ZG)
            {
                Task=sctuInShuttlePickErrAlarm;
            }
            break;
        case sctuInShuttlePickErrAlarm:
            ret=ShowErrorMessage("JAM0111", K_RETRY|K_SKIP, MInArmX, false, "G");                                       //Steven 20210806 : Fixed for Device Mapping (ZG)
            InArmSuck.Suck[0][3].Reset();
            if(ret==K_SKIP)
            {
                if(iSht==0)
                    FLCarryKit.SetItemData(iShuttleY, iShuttleX, NULL_IC);
                else
                    BLCarryKit.SetItemData(iShuttleY, iShuttleX, NULL_IC);
                Task=sctuInit;
            }
            else
            {
                Task=sctuInXYToShuttle;
            }
            break;
        case sctuInZShutleUp:
            if(iContactMode==CONTACT_DEVICE_MAP_CHECK &&
               (TestIF_File.iTestMode==DualSite ||
                TestIF_File.iTestMode==QualSite2X2 ||
                TestIF_File.iTestMode==_8Site2X4 ||
                TestIF_File.iTestMode==QualSite1X4))                            //Steven 20220510 : For QTI SD Device Map Function
            {
                flag=MoveInArmZToPlateSafe(Task);
            }
            else
            {
                flag=MOT[MInArmZG].MotorMove(0);
            }

            if(flag)                                                            //Steven 20210806 : Fixed for Device Mapping (ZG)
            {
                Task=sctuInSerachLoader;
            }
            break;
        case sctuInSerachLoader:
            bHasICToPlace=false;
            iArmRow=0;
            iArmCol=3;
            if(iContactMode==CONTACT_DEVICE_MAP_CHECK)                          //Steven 20191009 : Device Map for Qualcomm
            {
                if(iContactMode==CONTACT_DEVICE_MAP_CHECK &&
                   (TestIF_File.iTestMode==DualSite ||
                    TestIF_File.iTestMode==QualSite2X2 ||
                    TestIF_File.iTestMode==_8Site2X4 ||
                    TestIF_File.iTestMode==QualSite1X4))                        //Steven 20220510 : For QTI SD Device Map Function
                {
                    for(int i=0; i<InArmSuck.iShtRow; i++)
                    {
                        for(int j=0; j<InArmSuck.iShtCol; j++)
                        {
                            if(bHasICToPlace==false && InArmSuck.Item[i][j]!=NULL_IC)
                            {
                                bInArmSuckActive[i][j]=true;
                                iLoaderX=InArmSuck.PordRec[i][j].GetLoaderX();
                                iLoaderY=InArmSuck.PordRec[i][j].GetLoaderY();
                                iArmRow=i;
                                iArmCol=j;
                                bHasICToPlace=true;
                            }
                        }
                    }
                }
                else
                {
                    for(int i=0; i<MAX_SOCKET_TOTAL; i++)
                    {
                        if(iDMCChannel[i]!=-1 && iDMCChannel[i]==TestIF_File.iSiteMap[iShuttleY][iShuttleX])
                        {
                            iDMCChannel[i]=-1;                                  //如果掉料或者歸零可能就死了
                            iLoaderX=iDMCTrayX[i];                              //Steven 20210806 : Fixed for Device Mapping
                            iLoaderY=iDMCTrayY[i];
                        }
                    }
                }
            }
            else
            {
                if(iSht==0)
                {
                    for(int j=0; j<MOT[MMTrayY].Tray.YItem; j++)
                    {
                        for(int i=0; i<MOT[MMTrayY].Tray.XItem; i++)
                        {
                            if(bHasICToPlace==false &&
                               MOT[MMTrayY].Tray.Data[i][j]==NULL_IC)           //kevin 20180322 add
                            {
                                iLoaderX=i;
                                iLoaderY=j;
                                bHasICToPlace=true;
                            }
                        }
                    }

                    if(bHasICToPlace==false)
                    {
                        FLCarryKit.SetNullIcToHasNullIc();
                        break;
                    }
                }
                else if(iSht==1)
                {
                    for(int j=0; j<MOT[MMTrayY].Tray.YItem; j++)
                    {
                        for(int i=0; i<MOT[MMTrayY].Tray.XItem; i++)
                        {
                            if(bHasICToPlace==false &&
                               MOT[MMTrayY].Tray.Data[i][j]==HAS_NULL_CLEAN_IC)
                            {
                                iLoaderX=i;
                                iLoaderY=j;
                                bHasICToPlace=true;
                            }
                        }
                    }

                    if(bHasICToPlace==false)
                    {
                        BLCarryKit.SetNullIcToHasNullIc();
                        break;
                    }
                }
            }

            if(bHasICToPlace)
            {
                Task=sctuInXYToLoad;
            }
            else
            {
                //這表示有問題!
            }
            break;
        case sctuInXYToLoad:
            iMovePitchX=iXpitchMaxX3;
            iMovePitchY=AutoCalculateInArmYClosePitch();
            iYVariable=GetInArmPitchY_9045(iMovePitchY, iOffsetPos);
            for(int i=0; i<X_PITCH_COUNT; i++)
                iXVariable[i]=GetInArmPitchX_9045(iMovePitchX, i, iOffsetPos);

            if(iArmCol==0)                                                      //Mylin 20220607 Debug In Arm Place IC to Loader Position Error ==>
                iXPos=Prod.XInArm_Tray_Pick[iArmRow][iArmCol]+iLoaderX*Prod.LoadForm.iXPitch+iXpitchMaxX2;
            else if(iArmCol==1)
                iXPos=Prod.XInArm_Tray_Pick[iArmRow][iArmCol]+iLoaderX*Prod.LoadForm.iXPitch+iXpitchMax;
            else if(iArmCol==2)
                iXPos=Prod.XInArm_Tray_Pick[iArmRow][iArmCol]+iLoaderX*Prod.LoadForm.iXPitch;
            else
                iXPos=Prod.XInArm_Tray_Pick[iArmRow][iArmCol]+iLoaderX*Prod.LoadForm.iXPitch-iXpitchMax;

            if(iArmRow==0)
                iYPos=Prod.YInArm_Tray_Pick[iArmRow][iArmCol]-iLoaderY*Prod.LoadForm.iYPitch;
            else
                iYPos=Prod.YInArm_Tray_Pick[iArmRow][iArmCol]-iLoaderY*Prod.LoadForm.iYPitch+iMovePitchY;

            if(USE_IN_Y_IS_AUTO_PITCH==true)                                    //Steven 20210806 : Fixed for Device Mapping  //JerryYang 20251218 : IN/OUT ARM支援不同模組
                iYPos-=iMovePitchY;

            if(InArmContinuousMove_9045(iXPos, iYPos, iXVariable, iYVariable, bZFlag, iZPos, false))
            {
                Task=sctuInZToLoadPut;
            }
            break;
        case sctuInZToLoadPut:
            CheckInArmSuckICFallDownToHasNullIC();                                                                                                              //JerryYang 20221122 : add掉料偵測
            if(MOT[MInArmZA+iArmRow+iArmCol*2].MotorMove2SpeedForPicker(Prod.ZInArm_Tray_Place[iArmRow][iArmCol], &ArmSpeed[InArm]))                            //Steven 20210806 : Fixed for Device Mapping (ZG)
            {
                if((AccessLevel>=1 || CosFunction.bOPCanPressStepAndTStart) &&                                                                                  //JerryYang 20221118 : add
                   (Sen[SnRKManualTStart].IsOn() ||
                   fOffSet->UseAutoOffsetFunction("Hot Plate"+AnsiString(2-iPlacePlate[0]))))
                {
                    bEnterOffset=false;
                    fMain->Pause("sctuInZToLoadPut");
                    Task=sctuInLoadPutTstart;
                    break;
                }
                InArmSuck.Suck[iArmRow][iArmCol].Reset();
                Task=sctuInLoadPut;
            }
            break;
        case sctuInLoadPutTstart:                                               //JerryYang 20221118 : add
            if(bEnterOffset==true)
            {
                bEnterOffset=false;
                Task=sctuInLoadPutTstartZsafe;
            }
            else
            {
                Task=sctuInZToLoadPut;
            }
            break;
        case sctuInLoadPutTstartZsafe:
            if(MoveInArmZToPlateSafe(Task))
            {
                Task=sctuInXYToLoad;
            }
            break;
        case sctuInLoadPut:
            if(InArmSuck.Suck[iArmRow][iArmCol].Destroy())
            {
                MOT[MMTrayY].SetTraySingleData(iLoaderX, iLoaderY, HAS_IC);
                InArmSuck.SetItemData(iArmRow, iArmCol, NULL_IC);
                bInArmCheckDestroyACT[iArmRow][iArmCol]=true;                   //JerryYang 20221118 : add回吸偵測
                Task=sctuInZLoadUp;
            }
            else if(InArmSuck.Suck[iArmRow][iArmCol].Error)
            {
            }
            break;
        case sctuInZLoadUp:
            if(MOT[MInArmZA+iArmRow+iArmCol*2].MotorMove(ZSafePos))             //Steven 20210806 : Fixed for Device Mapping (ZG)
            {
                if(InArmSuck.HasRealIC())
                {
                    Task=sctuInZShutleUp;
                }
                else
                {
                    Task=sctuInit;
                }
            }
            break;
        case sctuInXYAway:
            iMovePitchX=iXpitchMaxX3;
            iMovePitchY=AutoCalculateInArmYClosePitch();
            iYVariable=GetInArmPitchY_9045(iMovePitchY, iOffsetPos);
            for(int i=0; i<X_PITCH_COUNT; i++)
                iXVariable[i]=GetInArmPitchX_9045(iMovePitchX, i, iOffsetPos);

            iLoaderY=Prod.LoadForm.iYItem-1;
            iXPos=Prod.XInArm_Tray_Pick[iArmRow][iArmCol]+iLoaderX*Prod.LoadForm.iXPitch-iMovePitchX/3;
            iYPos=Prod.YInArm_Tray_Pick[iArmRow][iArmCol]-iLoaderY*Prod.LoadForm.iYPitch;

            if(InArmContinuousMove_9045(iXPos, iYPos, iXVariable, iYVariable, bZFlag, iZPos, false))
            {
                Task=sctuInit;
                bResult=true;
            }
            break;
    }
    return bResult;
}
