//---------------------------------------------------------------------------
void __fastcall TfContact::TimerEPTimer(TObject *Sender)
{
    double dValue=0.0;
    if(EP_Install==3 && fShow==true)                                            //Steven 20160630
    {
        labEPValue->Caption=ADAM_ReadPA(&dValue);                               //20111217 ChungHung  //wei 20220309 Add EP Return Voltage
    }

    if(EP_Install==5 && fShow==true)
    {
        labEPValue->Caption=ADAM_ReadPA(&dValue, 0);
        labEPValue_1032->Caption=ADAM_ReadPA(&dValue, 1);
    }

    if(REAL_TIME_CCD)                                                           //Sam 20240711 : RTC Auto Tuning
    {
        cbRTCAutoTuning->Visible=(!COM2->bCCDDummyRum                  &&
                                   IniConfig.bD74RTCAutoTuning         &&
                                   fSecurity->Insufficient(176, false) &&
                                   COM2->bRTCVerSupportAutoTurnning);

        if(bOldRTCAutoTuning!=cbRTCAutoTuning->Visible)
        {
            bOldRTCAutoTuning=cbRTCAutoTuning->Visible;
            if(CUSTOMER_CODE==CC_SIGURD_HUKOU)
            {
                cbRTCAutoTuning->Checked=cbRTCAutoTuning->Visible;
                cbRTCAutoTuning->Enabled=!cbRTCAutoTuning->Visible;
                bRTCAutoTuning=cbRTCAutoTuning->Visible;
            }
            else
            {
                cbRTCAutoTuning->Checked=false;
            }
        }
    }
    else
    {
        cbRTCAutoTuning->Visible=false;
        cbRTCAutoTuning->Checked=false;
    }
    //==> Eastsun 20260526 #026-1.5L Ifor 20230612 add:Contact 頁面顯示ATC 等待時間倒數
    if(CUSTOMER_CODE==CC_KYEC_LEE && bEnable_KLT_Function==false && bCheckATCTemp==true &&
       Temperature.bATCActiveCooling==true && iATCTempWaitTimer!=0)
    {
        AnsiString S1;
        S1.sprintf("ATC Temp Wait :%02d sec", iATCTempWaitTimer);
        lblATCTempWait->Caption=S1;
        lblATCTempWait->Visible=true;
    }
    else
    {
        lblATCTempWait->Visible=false;
    }
    //<== Eastsun 20260526 #026-1.5L
    }
