//---------------------------------------------------------------------------
void __fastcall TfContact::btnIndexArmJogMove_UpClick(TObject *Sender)          //Ifor 20170105 (Steven) add KYEC 要求Contact Test 可上下調整Arm Offset 高度 +3 ~ -1   //Alick 20170116 modify -2~+2
{
    int ArmCmdPos[2]={0, 0}, iMovePos=0, iTotalPos=0;
    double dLimitPos;

    if(iContactMode==CONTACT_TEST)
    {
        ArmCmdPos[0]=int(atof(edContactHeight1->Text.c_str())*100.0+atof(edContactOffsetArm1->Text.c_str())*100.0);
        ArmCmdPos[1]=int(atof(edContactHeight2->Text.c_str())*100.0+atof(edContactOffsetArm2->Text.c_str())*100.0);
        iMovePos    =int(atof(cbIndexArmJogMove_mm->Text.c_str())*100.0);

        if(iIndexStatus==Z1Down_Z2Up)
        {
            dLimitPos=atof(cbIndexArmJogMove_mm->Text.c_str())+atof(edContactOffsetArm1->Text.c_str());
            if(dLimitPos>InputLimit.dContactHigh ||
               atof(edContactOffsetArm1->Text.c_str())>InputLimit.dContactHigh)
            {
//                ShowMyMessage("Index Arm1 Over Jog Move Limit");              //Ifor 20170125 (Steven) KYEC 喬智說不需Alarm
            }
            else
            {
                iTotalPos=iMovePos+ArmCmdPos[0];
                edContactOffsetArm1->Text=dLimitPos;
                iContactJogMove=iTotalPos;                                      //Alick 20170116 add
                btnIndexArmJogMove_Up->Enabled=false;                           //Alick 20170116 add
                btnIndexArmJogMove_Down->Enabled=false;                         //Alick 20170116 add
                bContactJogFlag=true;                                           //Alick 20170116 add
                MOT[MTestZ1].Gali_MotMove(iContactJogMove, GotIndexZSpeed(iSpeedZ*1000));                               //JimmyChiu 20211028 : All speed can set by speed setting.
            }
        }
        else if(iIndexStatus==Z1Up_Z2Down)
        {
            dLimitPos=atof(cbIndexArmJogMove_mm->Text.c_str())+atof(edContactOffsetArm2->Text.c_str());
            if(dLimitPos>InputLimit.dContactHigh ||
               atof(edContactOffsetArm2->Text.c_str())>InputLimit.dContactHigh)
            {
//                ShowMyMessage("Index Arm2 Over Jog Move Limit");              //Ifor 20170125 (Steven) KYEC 喬智說不需Alarm
            }
            else
            {
                iTotalPos=iMovePos+ArmCmdPos[1];
                edContactOffsetArm2->Text=dLimitPos;
                iContactJogMove=iTotalPos;                                      //Alick 20170116 add
                btnIndexArmJogMove_Up->Enabled=false;                           //Alick 20170116 add
                btnIndexArmJogMove_Down->Enabled=false;                         //Alick 20170116 add
                bContactJogFlag=true;                                           //Alick 20170116 add
                MOT[MTestZ2].Gali_MotMove(iContactJogMove, GotIndexZSpeed(iSpeedZ*1000));                               //JimmyChiu 20211028 : All speed can set by speed setting.
            }
        }
    }
}
