            edContactOffsetArm1->Visible    =true;
            edContactOffsetArm2->Visible    =true;
            labShtOffset->Visible           =true;
            edShtPickOffset1->Visible       =true;
            edShtPickOffset2->Visible       =true;
            lblShtPickOfsMM->Visible        =true;
            lblContactOfsMM->Visible        =true;
            edContactHeight1->Enabled       =false;
            edContactHeight2->Enabled       =false;
            edPickUp1->Enabled              =false;
            edPickUp2->Enabled              =false;
            IniConfig.bRemeberAutoHeight    =true;                              //ChungHung 20120725 Amkor_K 要可以記住AutoHeight的值，除非重新K高度 但選單Arm時只移動-50
            IniConfig.bChangeKitNoHardStop  =true;                              //jou 2015-12-08 Xilinx 驗證用
