//---------------------------------------------------------------------------
void TfContact::ATC_SwitchTjSignal(int iIndexArm, bool bSnedArmDown)            //Ifor 20210622 add: ATC Switch TJ
{
    if(iIndexArm==1)
    {
        if(ATC_SYSTEM==eNewATCSystem &&                                         //Ifor 20241009 add: send ATC which ARM
           Temperature.bATCActiveCooling==true)
        {
            ATC_InterfaceForm->HandlerArm(0);
        }

        if(bSnedArmDown==true)
            fMain->SendMSG_CMD(MSG_CMD_Arm1Down);                               //Steven 20150304 : Add GPIB LOG
        iWhichArmDown=1;                                                        //JerryYang 20200316 add SVID 哪支arm下壓在測區
        if(SW[SwTjSignal01].Enable==true)
            SW[SwTjSignal01].On();
        if(SW[SwTjSignal02].Enable==true)
            SW[SwTjSignal02].On();
        if(SW[SwTjSignal03].Enable==true)
            SW[SwTjSignal03].On();
        if(SW[SwTjSignal04].Enable==true)
            SW[SwTjSignal04].On();

        if(SW[SwTjSignal05].Enable==true)
            SW[SwTjSignal05].Off();
        if(SW[SwTjSignal06].Enable==true)
            SW[SwTjSignal06].Off();
        if(SW[SwTjSignal07].Enable==true)
            SW[SwTjSignal07].Off();
        if(SW[SwTjSignal08].Enable==true)
            SW[SwTjSignal08].Off();
    }
    else if(iIndexArm==2)
    {
        if(ATC_SYSTEM==eNewATCSystem &&                                         //Ifor 20241009 add: send ATC which ARM
           Temperature.bATCActiveCooling==true)
        {
            ATC_InterfaceForm->HandlerArm(1);
        }

        if(bSnedArmDown==true)
            fMain->SendMSG_CMD(MSG_CMD_Arm2Down);                               //Steven 20150304 : Add GPIB LOG
        iWhichArmDown=2;                                                        //JerryYang 20200316 add SVID 哪支arm下壓在測區

        if(SW[SwTjSignal01].Enable==true)
            SW[SwTjSignal01].Off();
        if(SW[SwTjSignal02].Enable==true)
            SW[SwTjSignal02].Off();
        if(SW[SwTjSignal03].Enable==true)
            SW[SwTjSignal03].Off();
        if(SW[SwTjSignal04].Enable==true)
            SW[SwTjSignal04].Off();

        if(SW[SwTjSignal05].Enable==true)
            SW[SwTjSignal05].On();
        if(SW[SwTjSignal06].Enable==true)
            SW[SwTjSignal06].On();
        if(SW[SwTjSignal07].Enable==true)
            SW[SwTjSignal07].On();
        if(SW[SwTjSignal08].Enable==true)
            SW[SwTjSignal08].On();
    }
}
//---------------------------------------------------------------------------
void TfContact::SetIndexDownPos()                                               //Steven 20211109 : 改成全域變數
{
    if(bUserDefMaxContactHeight)                                                //Steven 20180412 : For new HT-9045高度較高
    {
        fIndexDownPos=dUserDefMaxContactHeight;
    }
    else if(MachineTypeChoice==Type_HT9046_LS)
    {
        fIndexDownPos=fIndexDownPos_for9046LS;
        if(CUSTOMER_CODE==CC_QUALCOMM && ATC_MixMode==eMixATC60_ATC33)          //Ifor 20260121 add
        {
            fIndexDownPos=fIndexDownPos-20;
        }
    }
    else if(ATC_SYSTEM!=eATCUninstall)                                          //wei 20160303 HT-9045HA -146
    {
        fIndexDownPos=fIndexDownPos_forATC;
    }
    else
    {
        if(CUSTOMER_CODE==CC_KYEC_LEE ||
           CUSTOMER_CODE==CC_KYEC_CHEN ||
           CUSTOMER_CODE==CC_KYEC_JCTHIU ||
           CUSTOMER_CODE==CC_DL_TEK   ||
           CUSTOMER_CODE==CC_KYEC_XILINX)                                       //Ifor 20161117 Kyec Z擋版往上拉5mm Z需多下降5mm  -135-5 =-140
        {
            fIndexDownPos=fIndexDownPos_for9045-5;
        }
        else
        {
            fIndexDownPos=fIndexDownPos_for9045;
        }
    }
}
