//------------------------------------------------------------------------------
//kevin 20220426 Contract mode Index Check
//------------------------------------------------------------------------------
int iIndexTask=1;
bool TfContact::DoIndecxCHECkFunction(bool reset)
{
    static int iSiteCount=0;
    static AnsiString ErrPart="";

    int &Task=iIndexTask;
    int iIndexUpPos=GetSocketCheckPos(Prod.TestZ1_Test);                        //Steven 20140620 : 整合為Function

    if(reset)
    {
        iIndexTask=1;
        return false;
    }

    switch(Task)
    {
        case 1:
            ADAM_WriteVoltage(DeviceForm.dPress);
            if(iSelectArm==0)                                                   //kevin 20220426 0: Arm1 Arm 2  1: Arm1  2: Arm2
                Task=100;
            else if(iSelectArm==1)
                Task=100;
            else
                Task=140;
            break;
        case 100:                                                               //Index1 移至中間 Index2 移至後面
            EPSwitchOnOff(eEPSwArm1);
            if(MOT[MTestY1].GalilTwoY_Move(Prod.TestY1_Middle, Prod.TestY2_Rear, iSpeedY, "DoTestHeadMotor 100"))
            {
                Task=101;
            }
            break;
        case 101:
            if(MOT[MTestZ1].Gali_MotMove(Prod.TestZ1_Test-Prod.TestZ1_Drop_Offset+iIndexUpPos, iSpeedFast))             //Eliot 2015-02-25 Above Socket Postion
            {
                TotalErrPart="";
                IndexStatus=Z1Down_Z2Up;
                Task=102;
            }
            break;
       case 102:
            IndexCheck4Site(true, 0, iSiteCount);
            Task=103;
            break;
       case 103:                                                                //kevin 20190531 index check 4 Site
            if(IndexCheck4Site(false, 0, iSiteCount))
            {
                iSiteCount++;
                if(iSiteCount<4)
                {
                    Task=102;
                }
                else
                {
                    Task=104;
                    iSiteCount=0;
                }
            }
            break;
        case 104:
            if(MOT[MTestZ1].Gali_Two_ZAxis_Move(Prod.TestZ1_Safe, iSpeedSlow, "DoContactIndex check 103"))
            {
                for(int i=0; i<FTestSuck.iShtRow; i++)
                {
                    for(int j=0; j<FTestSuck.iShtCol; j++)
                    {
                        FTestSuck.Suck[i][j].Normal();
                    }
                }

                if(TotalErrPart!="")
                {
                    Task=105;
                }
                else
                {
                    if(iSelectArm==1)
                        Task=150;
                    else
                        Task=140;
                }
            }
            break;
        case 105:
            if(MOT[MTestY1].GalilTwoY_Move(Prod.TestY1_Front, Prod.TestY2_Rear, iSpeedY, "DoContactIndex check 104 "))
                Task=106;
            break;
        case 106:
            bIsTestSitICFallDown=true;                                          //Steven 20130613
            ShowErrorMessage("WAR0310", K_RETRY, MTestY1, false, TotalErrPart);
            TotalErrPart="";
            Task=1;
            break;
        case 140:                                                               //Arm 2  移至中間
            EPSwitchOnOff(eEPSwBoth);
            if(MOT[MTestY1].GalilTwoY_Move(Prod.TestY1_Front, Prod.TestY2_Middle, iSpeedY, "DoTestHeadMotor 110"))
                Task=141;
            break;
        case 141:
            if(MOT[MTestZ2].Gali_MotMove(Prod.TestZ2_Test-Prod.TestZ2_Drop_Offset, iSpeedSlow))
            {
                TotalErrPart="";
                IndexCheck4Site(true, 0, iSiteCount);
                IndexStatus=Z1Up_Z2Down;
                Task=142;
            }
            break;
       case 142:
            IndexCheck4Site(true, 1, iSiteCount);
            Task=143;
            break;
       case 143:                                                                //kevin 20190531 index check 4 Site
            if(IndexCheck4Site(false, 1, iSiteCount))
            {
                iSiteCount++;
                if(iSiteCount<4)
                {
                    Task=142;
                }
                else
                {
                    Task=145;
                    iSiteCount=0;
                }
            }
            break;
        case 145:
            if(MOT[MTestZ2].Gali_Two_ZAxis_Move(Prod.TestZ2_Safe, iSpeedSlow, "DoContactIndex check 145"))
            {
                for(int i=0; i<BTestSuck.iShtRow; i++)
                {
                    for(int j=0; j<BTestSuck.iShtCol; j++)
                    {
                        BTestSuck.Suck[i][j].Normal();
                    }
                }

                if(TotalErrPart!="")
                   Task=146;
                else
                   Task=150;
            }
            break;
        case 146:
            if(MOT[MTestY1].GalilTwoY_Move(Prod.TestY1_Front, Prod.TestY2_Rear, iSpeedY, "DoContactIndex check 104 "))
                Task=147;
            break;
        case 147:
                bIsTestSitICFallDown=true;                                      //Steven 20130613
                ShowErrorMessage("WAR0310", K_RETRY, MTestY2, false, TotalErrPart);
                TotalErrPart="";
                Task=1;
            break;
        case 150:
            return true;
    }
    return false;
}
